// 1. Health check
app.get("/health", (req, res) => res.status(200).send("OK"));
app.get("/healthz", (req, res) => res.status(200).send("OK"));
app.get("/readyz", (req, res) => {
  const ready = isOnlineRuntimeUsable();
  return res.status(ready ? 200 : 503).json({
    status: ready ? 'ready' : 'starting',
    ready,
    mode: storageMode,
    dbConnected: Boolean(pool && !isDbQuotaExceeded),
    hydrated: Boolean(hasHydratedPersistentState),
    readyAt: onlineRuntimeReadyAt
  });
});
app.get("/api/health", (req, res) => {
  const ready = isOnlineRuntimeUsable();
  const dbConnected = Boolean(pool && !isDbQuotaExceeded);
  const hydrated = Boolean(hasHydratedPersistentState);
  const reason = ready
    ? null
    : (!dbConnected
      ? 'CLOUD_SQL_NOT_CONNECTED'
      : (!hydrated ? 'HYDRATION_PENDING' : 'RUNTIME_STARTING'));
  res.status(200).json({
    status: ready ? "ok" : "starting",
    ready,
    mode: storageMode,
    dbConnected,
    hydrated,
    reason,
    readyAt: onlineRuntimeReadyAt
  });
});

app.get("/api/check-connection", async (req, res) => {
  const status = {
    firestore: false,
    cloudinary: false,
    error: null as string | null
  };

  // Check Firestore
  if (db) {
    try {
      await getDoc(doc(db, 'app_store', 'health_check_dummy'));
      status.firestore = true;
    } catch (e: any) {
      status.error = `Firestore: ${e.message}`;
    }
  }

  // Check Cloudinary
  if (process.env.CLOUDINARY_CLOUD_NAME) {
    try {
      await cloudinary.api.ping();
      status.cloudinary = true;
    } catch (e: any) {
      status.error = (status.error ? status.error + " | " : "") + `Cloudinary: ${e.message}`;
    }
  }

  res.json(status);
});

// Server-Side Authentication & Session Engine (JWT/HMAC)
const JWT_SECRET = process.env.JWT_SECRET || "";
if (!JWT_SECRET) {
  console.error("======================================================================================");
  console.error("⚠️  CRITICAL WARNING: JWT_SECRET is not set in the environment variables!");
  console.error("⚠️  Any requests requiring authentication will fail until JWT_SECRET is configured.");
  console.error("======================================================================================");
}

const requestedJwtTtl = Number(process.env.JWT_TTL_SECONDS || '');
const JWT_TTL_SECONDS = Number.isFinite(requestedJwtTtl) && requestedJwtTtl >= 900 && requestedJwtTtl <= (90 * 24 * 3600)
  ? Math.floor(requestedJwtTtl)
  : (isOnlineMode ? 12 * 3600 : 30 * 24 * 3600);

function createRealtimeToken(user: any): string {
  if (!JWT_SECRET) throw new Error('JWT_SECRET is required for realtime authentication.');
  const payload = {
    id: String(user.id || ''),
    role: String(user.role || '').toLowerCase(),
    madrasahId: String(user.madrasahId || 'default'),
    scope: 'realtime',
    exp: Math.floor(Date.now() / 1000) + 600
  };
  const encoded = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signature = crypto.createHmac('sha256', JWT_SECRET).update(`realtime.${encoded}`).digest('base64url');
  return `${encoded}.${signature}`;
}

function verifyRealtimeToken(token: string): any | null {
  if (!JWT_SECRET || !token || typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  const [encoded, signature] = parts;
  const expected = crypto.createHmac('sha256', JWT_SECRET).update(`realtime.${encoded}`).digest('base64url');
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  try {
    const payload = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf8'));
    if (payload.scope !== 'realtime') return null;
    if (!payload.exp || Number(payload.exp) < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch {
    return null;
  }
}

interface AuthSession {
  id: string;
  role: string;
  username: string;
  name?: string;
  classId?: string;
  madrasahId?: string;
  madrasahSlug?: string;
  authStamp: string;
  exp: number;
}

function authSessionStamp(role: any, id: any, username: any, madrasahId: any, credentialProof: any): string {
  if (!JWT_SECRET || !credentialProof) return "";
  const normalized = [
    String(role || '').trim().toLowerCase(),
    String(id || '').trim(),
    String(username || '').trim().toLowerCase(),
    String(madrasahId || 'default').trim(),
    String(credentialProof)
  ].join("\n");
  return crypto.createHmac("sha256", JWT_SECRET)
    .update(`AUTH_SESSION_CREDENTIAL_STAMP_V2\n${normalized}`)
    .digest("base64url");
}

function constantTimeStringEqual(left: any, right: any): boolean {
  const a = Buffer.from(String(left || ''));
  const b = Buffer.from(String(right || ''));
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function canonicalAuthTenantIdentity(value: any): string {
  const raw = String(value || 'default').trim();
  const normalized = raw.toLowerCase();
  const matched = (madrasahs || []).find((m: any) =>
    String(m?.id || '').trim() === raw ||
    String(m?.slug || '').trim().toLowerCase() === normalized
  );
  return String(matched?.id || raw).trim() || 'default';
}

function authRecordMatchesTokenTenant(record: any, tenantId: any): boolean {
  // AUTH_TENANT_ID_SLUG_COMPAT_V2: legacy records may store only madrasahSlug while
  // newer tokens carry the canonical madrasah id. Treat both references as the same tenant.
  const target = canonicalAuthTenantIdentity(tenantId);
  const values = [
    String(record?.madrasahId || '').trim(),
    String(record?.madrasahSlug || '').trim()
  ].filter(Boolean);
  if (values.length === 0) return target === canonicalAuthTenantIdentity('default');
  return values.some((value) => canonicalAuthTenantIdentity(value) === target);
}

function validateAuthSessionAgainstCurrentState(session: AuthSession): boolean {
  // AUTH_SESSION_CREDENTIAL_STAMP_V2: tokens are bound to the live account record.
  // Password/username/role changes, account deletion, and tenant deactivation revoke
  // an already-issued token immediately instead of waiting for its TTL.
  if (!session || !session.authStamp) return false;

  const role = String(session.role || '').trim().toLowerCase();
  const id = String(session.id || '').trim();
  const username = String(session.username || '').trim();
  const tenantId = String(session.madrasahId || 'default').trim() || 'default';
  const stampMatches = (credential: any, expectedRole = role, expectedUsername = username, expectedTenant = tenantId) =>
    constantTimeStringEqual(
      session.authStamp,
      authSessionStamp(expectedRole, id, expectedUsername, expectedTenant, credential)
    );

  if (role === 'bos' || role === 'superadmin') {
    const bossUser = String(process.env.BOSS_USERNAME || '').trim();
    const bossPass = String(process.env.BOSS_PASSWORD || '');
    return isBossRuntimeEnabled() &&
      id === 'BOSS' &&
      username.toLowerCase() === bossUser.toLowerCase() &&
      stampMatches(bossPass, 'bos', bossUser, 'default');
  }

  const sessionTenantCanonical = canonicalAuthTenantIdentity(tenantId);
  const sessionMadrasah = (madrasahs || []).find((m: any) =>
    String(m.id) === sessionTenantCanonical ||
    String(m.slug || '').toLowerCase() === String(tenantId || '').toLowerCase()
  );
  // OFFLINE_TENANT_STATUS_BYPASS_V1: BOSS account status is a cloud/online control.\n  // A local APP_MODE=offline installation must remain usable even when the last\n  // synchronized madrasah record is marked inactive by BOSS.\n  if (!sessionMadrasah || (isOnlineMode && sessionMadrasah.isActive === false)) return false;

  if (role === 'admin' || role === 'administrator') {
    const targetMadrasah = sessionMadrasah;

    if (id === 'ADMIN') {
      const currentUsername = String(appSettings?.adminUser || 'admin').trim();
      const currentCredential = String(appSettings?.adminPass || '');
      return Boolean(currentCredential) &&
        username.toLowerCase() === currentUsername.toLowerCase() &&
        stampMatches(currentCredential, 'admin', currentUsername, String(targetMadrasah.id || tenantId));
    }

    if (id !== `ADMIN_${String(targetMadrasah.id)}`) return false;
    const currentUsername = String(targetMadrasah.adminUser || '').trim();
    const currentCredential = String(targetMadrasah.adminPass || '');
    return Boolean(currentUsername && currentCredential) &&
      username.toLowerCase() === currentUsername.toLowerCase() &&
      stampMatches(currentCredential, 'admin', currentUsername, String(targetMadrasah.id || tenantId));
  }

  if (role === 'teacher' || role === 'guru') {
    const teacher = (teachers || []).find((item: any) =>
      String(item?.id || '') === id && authRecordMatchesTokenTenant(item, tenantId)
    );
    if (!teacher) return false;
    const currentUsername = String(teacher.username || teacher.nip || '').trim();
    const currentCredential = String(teacher.password || '');
    return Boolean(currentUsername && currentCredential) &&
      username.toLowerCase() === currentUsername.toLowerCase() &&
      stampMatches(currentCredential, 'teacher', currentUsername, tenantId);
  }

  if (['student', 'siswa', 'class_leader', 'ketua_kelas'].includes(role)) {
    const student = (students || []).find((item: any) =>
      String(item?.id || '') === id && authRecordMatchesTokenTenant(item, tenantId)
    );
    if (!student) return false;
    const currentRole = normalizeStudentStoredRole(student.role);
    const currentUsername = String(student.username || student.nis || '').trim();
    const currentCredential = String(student.password || '');
    return Boolean(currentUsername && currentCredential) &&
      role === currentRole &&
      username.toLowerCase() === currentUsername.toLowerCase() &&
      stampMatches(currentCredential, currentRole, currentUsername, tenantId);
  }

  return false;
}

function createAuthToken(user: any, credentialProof: any): string {
  if (!JWT_SECRET) {
    throw new Error("JWT_SECRET is required but not configured in the environment variables.");
  }
  if (!credentialProof) {
    throw new Error("Credential proof is required to issue an authenticated session.");
  }
  const header = { alg: "HS256", typ: "JWT" };
  const role = String(user.role || (user.nip ? 'teacher' : (user.nis ? 'student' : 'admin'))).toLowerCase();
  const username = String(user.username || user.nis || user.nip || '');
  const madrasahId = String(user.madrasahId || 'default');
  const payload: AuthSession = {
    id: String(user.id),
    role,
    username,
    name: user.name || '',
    classId: user.classId || user.class_id || '',
    madrasahId,
    madrasahSlug: user.madrasahSlug || '',
    authStamp: authSessionStamp(role, user.id, username, madrasahId, credentialProof),
    exp: Math.floor(Date.now() / 1000) + JWT_TTL_SECONDS
  };
  const b64Header = Buffer.from(JSON.stringify(header)).toString("base64url");
  const b64Payload = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const signature = crypto.createHmac("sha256", JWT_SECRET).update(`${b64Header}.${b64Payload}`).digest("base64url");
  return `${b64Header}.${b64Payload}.${signature}`;
}

function verifyAuthToken(token: string): AuthSession | null {
  if (!JWT_SECRET) {
    console.error("verifyAuthToken failed: JWT_SECRET is not configured in the environment.");
    return null;
  }
  if (!token || typeof token !== "string") return null;
  const parts = token.trim().split(".");
  if (parts.length !== 3) return null;
  const [b64Header, b64Payload, signature] = parts;
  const expectedSig = crypto.createHmac("sha256", JWT_SECRET).update(`${b64Header}.${b64Payload}`).digest("base64url");
  if (!constantTimeStringEqual(signature, expectedSig)) return null;
  try {
    const payload = JSON.parse(Buffer.from(b64Payload, "base64url").toString("utf-8")) as AuthSession;
    if (!payload.exp || payload.exp < Math.floor(Date.now() / 1000)) return null;
    if (!validateAuthSessionAgainstCurrentState(payload)) return null;
    return payload;
  } catch (e) {
    return null;
  }
}

// Learning-only compatibility validator.
// Signature and expiry remain mandatory. Only the mutable account-state binding
// is skipped for Materi Ajar; its handlers still enforce tenant/identity/role.
function verifyLearningAuthToken(token: string): AuthSession | null {
  if (!JWT_SECRET || !token || typeof token !== "string") return null;
  const parts = token.trim().split(".");
  if (parts.length !== 3) return null;
  const [b64Header, b64Payload, signature] = parts;
  const expectedSig = crypto.createHmac("sha256", JWT_SECRET)
    .update(b64Header + "." + b64Payload)
    .digest("base64url");
  if (!constantTimeStringEqual(signature, expectedSig)) return null;
  try {
    const payload = JSON.parse(Buffer.from(b64Payload, "base64url").toString("utf-8")) as AuthSession;
    if (!payload.id || !payload.role || !payload.username || !payload.authStamp) return null;
    if (!payload.exp || payload.exp < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch {
    return null;
  }
}

// Secure backward-compatible password hashing helper functions with memory-hard scrypt KDF
function hashPassword(plainText: string): string {
  if (!plainText) return "";
  const str = String(plainText).trim();
  if (str.startsWith("scrypt$") && str.split("$").length === 6) {
    return str; // Already hashed
  }
  if (str.startsWith("sha256$") && str.split("$").length === 3) {
    return str; // Legacy hash
  }
  const salt = crypto.randomBytes(16).toString("hex");
  const derivedKey = crypto.scryptSync(str, salt, 64, { N: 16384, r: 8, p: 1 });
  const hash = derivedKey.toString("hex");
  return `scrypt$16384$8$1$${salt}$${hash}`;
}

function generateTemporaryStudentPassword(): string {
  // 12 URL-safe random characters. Returned once through the credentials payload.
  return crypto.randomBytes(9).toString('base64url');
}

function verifyPassword(plainText: string, hashedPassword: string): boolean {
  if (!plainText || !hashedPassword) return false;
  const pStr = String(plainText).trim();
  const hStr = String(hashedPassword).trim();
  
  if (hStr.startsWith("scrypt$")) {
    const parts = hStr.split("$");
    if (parts.length !== 6) return false;

    const N = parseInt(parts[1], 10);
    const r = parseInt(parts[2], 10);
    const p = parseInt(parts[3], 10);
    const salt = parts[4];
    const expectedHash = parts[5];

    const derivedKey = crypto.scryptSync(
      pStr,
      salt,
      64,
      { N, r, p }
    );

    const actualHash = derivedKey.toString("hex");

    return crypto.timingSafeEqual(
      Buffer.from(actualHash, "hex"),
      Buffer.from(expectedHash, "hex")
    );
  }
  
  if (hStr.startsWith("sha256$")) {
    const parts = hStr.split("$");
    if (parts.length !== 3) return false;
    const salt = parts[1];
    const hash = parts[2];
    const computedHash = crypto.createHmac("sha256", salt).update(pStr).digest("hex");
    return computedHash === hash;
  }
  
  return pStr === hStr;
}

async function verifyPasswordAsync(plainText: string, hashedPassword: string): Promise<boolean> {
  if (!plainText || !hashedPassword) return false;
  const pStr = String(plainText).trim();
  const hStr = String(hashedPassword).trim();
  if (!hStr.startsWith("scrypt$")) return verifyPassword(pStr, hStr);
  const parts = hStr.split("$");
  if (parts.length !== 6) return false;
  const N = parseInt(parts[1], 10);
  const r = parseInt(parts[2], 10);
  const p = parseInt(parts[3], 10);
  const salt = parts[4];
  const expectedHash = parts[5];
  if (!Number.isFinite(N) || !Number.isFinite(r) || !Number.isFinite(p) || !salt || !expectedHash) return false;
  let derivedKey: Buffer;
  try {
    derivedKey = await new Promise<Buffer>((resolve, reject) => {
      crypto.scrypt(pStr, salt, 64, { N, r, p }, (err, key) => {
        if (err) reject(err);
        else resolve(key as Buffer);
      });
    });
  } catch {
    return false;
  }
  const expectedBuffer = Buffer.from(expectedHash, "hex");
  if (derivedKey.length !== expectedBuffer.length) return false;
  return crypto.timingSafeEqual(derivedKey, expectedBuffer);
}
function getAuthUser(req: any): AuthSession | null {
  // 1. Authorization: Bearer <token>
  const authHeader = req.headers?.authorization || req.headers?.Authorization;
  if (authHeader && typeof authHeader === 'string' && authHeader.startsWith('Bearer ')) {
    const token = authHeader.slice(7).trim();
    const verified = verifyAuthToken(token);
    if (verified) return verified;
  }
  // 2. x-auth-token header
  const xAuthToken = req.headers ? (req.headers['x-auth-token'] || req.headers['X-Auth-Token']) : null;
  if (xAuthToken && typeof xAuthToken === 'string') {
    const verified = verifyAuthToken(xAuthToken.trim());
    if (verified) return verified;
  }
  return null;
}

function getLearningAuthUser(req: any): AuthSession | null {
  const authHeader = req.headers?.authorization || req.headers?.Authorization;
  if (authHeader && typeof authHeader === 'string' && authHeader.startsWith('Bearer ')) {
    const verified = verifyLearningAuthToken(authHeader.slice(7).trim());
    if (verified) return verified;
  }
  const xAuthToken = req.headers ? (req.headers['x-auth-token'] || req.headers['X-Auth-Token']) : null;
  if (xAuthToken && typeof xAuthToken === 'string') {
    const verified = verifyLearningAuthToken(String(xAuthToken).trim());
    if (verified) return verified;
  }
  const queryToken = String(req.query?.auth || '').trim();
  if (queryToken) {
    const verified = verifyLearningAuthToken(queryToken);
    if (verified) return verified;
  }
  return null;
}

function requireAuth(req: any, res: any, next: any) {
  if (isOfflineMode && !isOfflineLicenseActive()) {
    return res.status(403).json({
      success: false,
      code: 'OFFLINE_LICENSE_REQUIRED',
      message: 'Lisensi instalasi offline tidak valid atau belum diaktivasi.'
    });
  }
  const authUser = req.user || getAuthUser(req);
  if (!authUser) {
    return res.status(401).json({ success: false, message: "Akses ditolak: Silakan login terlebih dahulu." });
  }
  req.user = authUser;
  next();
}

function requireRole(allowedRoles: string[]) {
  return (req: any, res: any, next: any) => {
    if (isOfflineMode && !isOfflineLicenseActive()) {
      return res.status(403).json({
        success: false,
        code: 'OFFLINE_LICENSE_REQUIRED',
        message: 'Lisensi instalasi offline tidak valid atau belum diaktivasi.'
      });
    }
    if (!req.user) {
      const authUser = getAuthUser(req);
      if (!authUser) {
        return res.status(401).json({ success: false, message: "Akses ditolak: Silakan login terlebih dahulu." });
      }
      req.user = authUser;
    }
    const role = String(req.user.role || '').toLowerCase();
    if (!allowedRoles.map(r => r.toLowerCase()).includes(role)) {
      return res.status(403).json({ success: false, message: `Akses ditolak: Role Anda (${role}) tidak diizinkan.` });
    }
    next();
  };
}

function resolveStudentId(req: any, authUser: AuthSession | null): string | null {
  if (!authUser) {
    return null;
  }
  const role = String(authUser.role || '').toLowerCase();
  // Server STRICTLY determines studentId from user login session if role is student/siswa!
  if (role === 'student' || role === 'siswa' || role === 'class_leader' || role === 'ketua_kelas') {
    return String(authUser.id);
  }
  // Teachers, proctors, and admins can query or submit for a student by ID
  if (role === 'teacher' || role === 'guru' || role === 'admin' || role === 'bos' || role === 'superadmin') {
    const candidate = req.body?.studentId || req.query?.studentId;
    return candidate ? String(candidate) : String(authUser.id);
  }
  return null;
}

// Poin 3: Role-based Question Sanitizer for Students (Strips answer, correctOptionText, explanation)
function sanitizeQuestionForStudent(q: any) {
  if (!q) return null;
  return {
    id: q.id,
    code: q.code || q.bankCode || q.groupCode || "",
    subjectId: q.subjectId || q.subject || "",
    classId: q.classId || q.className || "",
    type: q.type || (q.options ? "mc" : "essay"),
    question: q.question,
    options: Array.isArray(q.options) ? q.options : [],
    imageUrl: q.imageUrl || q.image || ""
  };
}

function sanitizeExamForStudent(exam: any) {
  if (!exam || typeof exam !== 'object') return exam;
  const {
    questions, answer, answerKey, correctAnswer, correctOptionText, explanation,
    masterQuestions, studentExamMasterQuestions, ...safe
  } = exam;
  if (Array.isArray(questions)) safe.questionCount = safe.questionCount ?? safe.qCount ?? questions.length;
  return safe;
}

function normalizeStudentStoredRole(role: any): 'student' | 'class_leader' {
  const normalized = String(role || '').trim().toLowerCase();
  return normalized === 'class_leader' || normalized === 'ketua_kelas' ? 'class_leader' : 'student';
}

function sanitizeLkpdForStudent(lkpd: any, studentId: string) {
  if (!lkpd || typeof lkpd !== 'object') return lkpd;
  const safe = { ...lkpd };
  safe.markers = (Array.isArray(lkpd.markers) ? lkpd.markers : []).map((marker: any) => {
    if (!marker || typeof marker !== 'object') return marker;
    const {
      answerKey, correctAnswer, correctOptionText, teacherAnswer, solution, rubric,
      explanation, ...safeMarker
    } = marker;
    return safeMarker;
  });
  safe.submissions = (Array.isArray(lkpd.submissions) ? lkpd.submissions : []).filter(
    (submission: any) => String(submission?.studentId || '') === String(studentId || '')
  );
  delete safe.answerKey;
  delete safe.correctAnswer;
  delete safe.correctOptionText;
  delete safe.teacherAnswer;
  delete safe.solution;
  delete safe.rubric;
  delete safe.explanation;
  return safe;
}

function sanitizeStudentPeerProfile(student: any) {
  if (!student || typeof student !== 'object') return null;
  return {
    id: student.id,
    nis: student.nis,
    name: student.name,
    classId: student.classId || student.class_id || '',
    class_id: student.class_id || student.classId || '',
    photo: normalizePhotoReferenceForClient(student.photo),
    photoHistory: normalizePhotoHistoryForClient(student.photoHistory),
    role: normalizeStudentStoredRole(student.role),
    gameAvatar: {
      presetId: String(student?.gameAvatar?.presetId || 'bintang').trim().toLowerCase() || 'bintang'
    }
  };
}

function sanitizeTeacherForStudent(teacher: any) {
  if (!teacher || typeof teacher !== 'object') return null;
  return {
    id: teacher.id,
    name: teacher.name,
    mapel: Array.isArray(teacher.mapel) ? teacher.mapel : (teacher.mapel ? [teacher.mapel] : []),
    photo: normalizePhotoReferenceForClient(teacher.photo),
    photoHistory: normalizePhotoHistoryForClient(teacher.photoHistory)
  };
}

function getTenantStudentIdentitySet(req: any): Set<string> {
  const ids = new Set<string>();
  for (const student of filterByMadrasah(students || [], req)) {
    if (student?.id !== undefined && student?.id !== null) ids.add(String(student.id));
    if (student?.nis !== undefined && student?.nis !== null) ids.add(String(student.nis));
  }
  return ids;
}

function filterStudentKeyedObjectForRequest(source: any, req: any): Record<string, any> {
  if (!source || typeof source !== 'object' || Array.isArray(source)) return {};
  const allowed = getTenantStudentIdentitySet(req);
  return Object.fromEntries(
    Object.entries(source).filter(([key]) => allowed.has(String(key)))
  );
}

function filterStudentLinkedListForRequest(source: any, req: any): any[] {
  if (!Array.isArray(source)) return [];
  const allowed = getTenantStudentIdentitySet(req);
  return source.filter((item: any) => {
    if (isItemForCurrentMadrasah(item, req)) return true;
    const sid = String(item?.studentId || item?.student_id || item?.nis || item?.userId || '');
    return sid && allowed.has(sid);
  });
}


function sanitizeSettingsForClient(settings: any) {
  if (!settings || typeof settings !== 'object') return settings || null;
  const safe: any = { ...settings };
  const explicitSensitive = new Set([
    'adminPass', 'password', 'jwtSecret', 'apiKey', 'geminiApiKey',
    'cloudinaryApiSecret', 'livekitApiSecret', 'databaseUrl', 'DATABASE_URL',
    'sqlPassword', 'localStoreSecret', 'tokenLockSecret', 'licensePrivateKey',
    'madrasahRegistrationInviteHash'
  ]);
  for (const key of Object.keys(safe)) {
    const lower = String(key).toLowerCase();
    if (explicitSensitive.has(key) || lower.includes('password') || lower.includes('passphrase') ||
        lower.includes('privatekey') || lower.includes('private_key') || lower.endsWith('secret') ||
        lower.includes('connectionstring')) delete safe[key];
  }
  return safe;
}

function sanitizeSettingsForPublic(settings: any) {
  const safe: any = sanitizeSettingsForClient(settings) || {};
  for (const key of [
    'adminUser',
    'turnUrl', 'turnUsername', 'turnCredential',
    'livekitUrl', 'livekitApiKey',
    'cloudinaryApiKey', 'cloudinaryCloudName',
    'madrasahRegistrationInviteHash'
  ]) delete safe[key];
  return safe;
}

// LIVEKIT_RUNTIME_CAPABILITY_V4: expose only a boolean capability to the browser.
// The API key/secret stay server-side and the same resolver is used by token minting.
// P2P_ONLY_LIVECAM_SERVER_V5: disable hosted LiveKit so configured credentials
// cannot consume quota. CBT livecam uses WebRTC P2P + snapshot fallback only.
function resolveLiveKitRuntimeConfig() {
  return { apiKey: '', apiSecret: '', serverUrl: '', configured: false, onlineLocalhost: false, disabled: true };
}

const tenantSettingsBlockedKeys = new Set([
  'adminUser', 'adminPass', 'password', 'jwtSecret', 'JWT_SECRET',
  'paymentAccounts', 'cbtTokenPrice',
  'apiKey', 'geminiApiKey',
  'cloudinaryCloudName', 'cloudinaryApiKey', 'cloudinaryApiSecret',
  'livekitUrl', 'livekitApiKey', 'livekitApiSecret',
  'databaseUrl', 'DATABASE_URL', 'sqlPassword',
  'localStoreSecret', 'LOCAL_STORE_SECRET',
  'tokenLockSecret', 'TOKEN_LOCK_SECRET',
  'licensePrivateKey', 'LICENSE_PRIVATE_KEY',
  'madrasahRegistrationMode', 'madrasahRegistrationInviteHash',
  '__tenantScopedSettingsV1'
]);

function sanitizeSettingsMutation(data: any, tenantScoped: boolean): any {
  const source = data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  const safe: any = {};
  for (const [key, value] of Object.entries(source)) {
    const lower = String(key).toLowerCase();
    if (
      lower.includes('password') || lower.includes('passphrase') ||
      lower.includes('privatekey') || lower.includes('private_key') ||
      lower.endsWith('secret') || lower.includes('connectionstring') ||
      key === '__tenantScopedSettingsV1'
    ) continue;
    if (tenantScoped && tenantSettingsBlockedKeys.has(key)) continue;
    safe[key] = value;
  }
  return safe;
}

function globalSettingsBase(): any {
  const base = { ...(appSettings || {}) };
  delete base.__tenantScopedSettingsV1;
  return base;
}

function normalizeAcademicRef(value: any): string {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
}

function isTeacherRequest(req: any): boolean {
  const role = String((req as any)?.user?.role || getAuthUser(req)?.role || '').toLowerCase();
  return role === 'teacher' || role === 'guru';
}

function teacherRecordForRequest(req: any): any | null {
  if (!isTeacherRequest(req)) return null;
  const authUser = (req as any).user || getAuthUser(req);
  const owned = filterByMadrasah(teachers || [], req).filter((teacher: any) =>
    String(teacher?.id || '') === String(authUser?.id || '')
  );
  return owned.length === 1 ? owned[0] : null;
}

function teacherAllowedSubjectsForRequest(req: any): any[] {
  if (!isTeacherRequest(req)) return filterByMadrasah(subjects || [], req);
  const teacher = teacherRecordForRequest(req);
  if (!teacher) return [];
  const assignments = (Array.isArray(teacher.mapel) ? teacher.mapel : (teacher.mapel ? [teacher.mapel] : []))
    .map((value: any) => String(value || '').trim())
    .filter(Boolean);
  if (assignments.length === 0) return [];

  return filterByMadrasah(subjects || [], req).filter((subject: any) => {
    const refs = [subject?.id, subject?.name, subject?.code].map((value: any) => String(value || '').trim());
    return assignments.some((assignment: string) => refs.some((ref: string) =>
      assignment === ref ||
      assignment.toLowerCase() === ref.toLowerCase() ||
      (normalizeAcademicRef(assignment) && normalizeAcademicRef(assignment) === normalizeAcademicRef(ref))
    ));
  });
}

function teacherCanAccessSubjectRef(req: any, subjectRef: any): boolean {
  if (!isTeacherRequest(req)) return true;
  const raw = String(subjectRef || '').trim();
  if (!raw) return false;
  const normalized = normalizeAcademicRef(raw);
  return teacherAllowedSubjectsForRequest(req).some((subject: any) => {
    const refs = [subject?.id, subject?.name, subject?.code].map((value: any) => String(value || '').trim());
    return refs.some((ref: string) =>
      raw === ref || raw.toLowerCase() === ref.toLowerCase() ||
      (normalized && normalized === normalizeAcademicRef(ref))
    );
  });
}

function questionBankGroupAllowedForTeacher(req: any, group: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!group || !isItemForCurrentMadrasah(group, req)) return false;
  if (teacherCanAccessSubjectRef(req, group.subjectId)) return true;

  const groupCode = String(group.code || '').trim().toLowerCase();
  if (!groupCode) return false;
  return filterByMadrasah(questions || [], req).some((question: any) =>
    String(question?.code || '').trim().toLowerCase() === groupCode &&
    teacherCanAccessSubjectRef(req, question?.subjectId || question?.subject)
  );
}

function questionAllowedForTeacher(req: any, question: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!question || !isItemForCurrentMadrasah(question, req)) return false;
  if (teacherCanAccessSubjectRef(req, question.subjectId || question.subject)) return true;

  const questionCode = String(question.code || question.bankCode || question.groupCode || '').trim().toLowerCase();
  if (!questionCode) return false;
  return filterByMadrasah(questionBankGroups || [], req).some((group: any) =>
    String(group?.code || '').trim().toLowerCase() === questionCode &&
    questionBankGroupAllowedForTeacher(req, group)
  );
}

function questionPayloadAllowedForTeacher(req: any, payload: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!payload || typeof payload !== 'object') return false;
  let candidate = { ...payload };
  if (payload.id !== undefined && payload.id !== null) {
    const existing = filterByMadrasah(questions || [], req).find((question: any) =>
      String(question?.id) === String(payload.id)
    );
    if (existing) candidate = { ...existing, ...payload };
  }
  candidate = tagNewRecord(candidate, req);
  return questionAllowedForTeacher(req, candidate);
}

function questionBankGroupsForRequest(req: any): any[] {
  const tenantGroups = filterByMadrasah(questionBankGroups || [], req);
  return isTeacherRequest(req)
    ? tenantGroups.filter((group: any) => questionBankGroupAllowedForTeacher(req, group))
    : tenantGroups;
}

function questionsForRequest(req: any): any[] {
  const tenantQuestions = filterByMadrasah(questions || [], req);
  return isTeacherRequest(req)
    ? tenantQuestions.filter((question: any) => questionAllowedForTeacher(req, question))
    : tenantQuestions;
}

function teacherCanUseExamPayload(req: any, examPayload: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!examPayload || typeof examPayload !== 'object') return false;
  if (String(examPayload.recordType || '').toUpperCase() === 'EVENT') return true;
  if (teacherHasActiveProctorAssignment(req, examPayload)) return true;

  const bankCode = String(examPayload.bankCode || '').trim().toLowerCase();
  if (bankCode) {
    const allowedBank = questionBankGroupsForRequest(req).some((group: any) =>
      String(group?.code || '').trim().toLowerCase() === bankCode
    );
    if (!allowedBank) return false;
  }

  const subjectRef = examPayload.subjectId || examPayload.subject;
  if (subjectRef && !teacherCanAccessSubjectRef(req, subjectRef)) return false;
  return Boolean(bankCode || subjectRef);
}

// TEACHER_EVENT_MUTATION_SCOPE_V3: event containers remain readable so teacher
// schedules stay grouped correctly, but only admin/BOSS may mutate EVENT records.
function teacherCanMutateExamPayload(req: any, examPayload: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!examPayload || typeof examPayload !== 'object') return false;
  if (String(examPayload.recordType || '').toUpperCase() === 'EVENT') return false;
  if (teacherHasActiveProctorAssignment(req, examPayload)) {
    const bankCode = String(examPayload.bankCode || '').trim().toLowerCase();
    const subjectRef = examPayload.subjectId || examPayload.subject;
    const bankOwned = !bankCode || questionBankGroupsForRequest(req).some((group: any) =>
      String(group?.code || '').trim().toLowerCase() === bankCode
    );
    const subjectOwned = !subjectRef || teacherCanAccessSubjectRef(req, subjectRef);
    if (!(bankOwned && subjectOwned && Boolean(bankCode || subjectRef))) return false;
  }
  return teacherCanUseExamPayload(req, examPayload);
}

function examsForRequest(req: any): any[] {
  const tenantExams = filterByMadrasah(exams || [], req);
  return isTeacherRequest(req)
    ? tenantExams.filter((exam: any) => teacherCanUseExamPayload(req, exam))
    : tenantExams;
}

// TEACHER_MONITOR_SCOPE_V2: all academic monitoring/sync paths reuse the same assignment boundary.
function teacherCanUseLkpdPayload(req: any, lkpdPayload: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!lkpdPayload || typeof lkpdPayload !== 'object') return false;
  const subjectRef = lkpdPayload.subjectId || lkpdPayload.subjectName || lkpdPayload.subject;
  return Boolean(subjectRef && teacherCanAccessSubjectRef(req, subjectRef));
}

function lkpdsForRequest(req: any): any[] {
  const tenantLkpds = filterByMadrasah(lkpdList || [], req);
  return isTeacherRequest(req)
    ? tenantLkpds.filter((lkpd: any) => teacherCanUseLkpdPayload(req, lkpd))
    : tenantLkpds;
}

function gradePayloadAllowedForTeacher(req: any, gradePayload: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!gradePayload || typeof gradePayload !== 'object') return false;
  const subjectRef = gradePayload.subjectId || gradePayload.subjectName || gradePayload.subject;
  return Boolean(subjectRef && teacherCanAccessSubjectRef(req, subjectRef));
}

function studentCanAccessExam(student: any, exam: any): boolean {
  if (!student || !exam) return false;
  const status = String(exam.status || '').trim().toLowerCase();
  // Legacy exams without status remain compatible. Explicit Draft/Inactive records
  // are teacher-only and are also rejected by attempt-context checks.
  if (status && !['active', 'aktif', 'published'].includes(status)) return false;
  const targets = Array.isArray(exam.classes)
    ? exam.classes.map((value: any) => String(value))
    : [exam.classId, exam.class_id, exam.className].filter(Boolean).map((value: any) => String(value));
  if (targets.length === 0 || targets.some((value: string) => value.toUpperCase() === 'ALL')) return true;
  const studentClasses = [student.classId, student.class_id, student.className, student.class]
    .filter(Boolean).map((value: any) => String(value));
  return targets.some((target: string) => studentClasses.includes(target));
}

function studentCanAccessLkpd(student: any, lkpd: any): boolean {
  if (!student || !lkpd) return false;
  const status = String(lkpd.status || '').trim().toLowerCase();
  // Legacy LKPD without status remain compatible; explicit inactive/draft records
  // stay hidden from student list/submission paths until a teacher activates them.
  if (status && !['active', 'aktif', 'published'].includes(status)) return false;
  const targets = Array.isArray(lkpd.classes)
    ? lkpd.classes.map((value: any) => String(value))
    : [lkpd.classId, lkpd.class_id, lkpd.className].filter(Boolean).map((value: any) => String(value));
  if (targets.length === 0 || targets.some((value: string) => value.toUpperCase() === 'ALL')) return true;
  const studentClasses = [student.classId, student.class_id, student.className, student.class]
    .filter(Boolean).map((value: any) => String(value));
  return targets.some((target: string) => studentClasses.includes(target));
}

function isLearningMaterialRecord(item: any): boolean {
  return Boolean(item && (String(item.recordType || '').toLowerCase() === 'learning_material' ||
    String(item.type || '').toLowerCase() === 'learning_material'));
}

function classTargetsFromLearningMaterial(material: any): string[] {
  // Multi-class fields are authoritative so removed legacy targets cannot leak.
  const explicitTargets = [
    ...(Array.isArray(material?.classes) ? material.classes : []),
    ...(Array.isArray(material?.targetClasses) ? material.targetClasses : [])
  ].filter((value: any) => value !== undefined && value !== null && String(value).trim() !== '');
  const targets = explicitTargets.length > 0 ? explicitTargets : [
    material?.classId,
    material?.class_id,
    material?.className,
    material?.targetClass
  ].filter((value: any) => value !== undefined && value !== null && String(value).trim() !== '');
  return Array.from(new Set(targets.map((value: any) => String(value).trim())));
}

function studentCanAccessLearningMaterial(student: any, material: any): boolean {
  if (!student || !material || !isLearningMaterialRecord(material)) return false;
  if (String(material.status || 'draft').toLowerCase() !== 'published') return false;
  const targets = classTargetsFromLearningMaterial(material);
  if (targets.length === 0 || targets.some((value: string) => ['ALL', 'SEMUA KELAS'].includes(value.toUpperCase()))) return true;
  const studentClasses = [student.classId, student.class_id, student.className, student.class]
    .filter(Boolean).map((value: any) => String(value).trim());
  const normalizedStudentClasses = new Set(studentClasses.map((value: string) => value.toLowerCase()));
  return targets.some((target: string) => normalizedStudentClasses.has(String(target).toLowerCase()));
}

function teacherCanUseLearningMaterialPayload(req: any, material: any): boolean {
  if (!isTeacherRequest(req)) return true;
  if (!material || typeof material !== 'object') return false;
  const subjectRef = material.subjectId || material.subjectName || material.subject || material.mapel;
  return Boolean(subjectRef && teacherCanAccessSubjectRef(req, subjectRef));
}

function learningCloudinaryPdfProxyUrl(value: any): string {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw);
    if (
      url.protocol === 'https:' &&
      url.hostname === 'res.cloudinary.com' &&
      /^\/(?:raw|image)\/upload\/v\d+\/madrasah_learning_assets\//i.test(url.pathname) &&
      /\.pdf$/i.test(url.pathname)
    ) {
      return '/api/learning-assets/inline-pdf?url=' + encodeURIComponent(raw);
    }
  } catch {}
  return '';
}

function protectLearningPdfDeliveryBlocks(rawBlocks: any): any[] {
  return (Array.isArray(rawBlocks) ? rawBlocks : []).map((raw: any) => {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return raw;
    if (String(raw.type || '').toLowerCase() !== 'pdf') return raw;
    if (String(raw.driveFileId || '').trim()) return { ...raw, url: '' };
    const proxyUrl = learningCloudinaryPdfProxyUrl(raw.url);
    return proxyUrl ? { ...raw, url: proxyUrl } : raw;
  });
}

function protectLearningMaterialAssetDelivery(material: any): any {
  if (!material || typeof material !== 'object') return material;
  return { ...material, blocks: protectLearningPdfDeliveryBlocks(material.blocks) };
}

function learningMaterialsForStaffRequest(req: any): any[] {
  const tenantMaterials = filterLessonPlansForRequest(req).filter(isLearningMaterialRecord);
  const visible = isTeacherRequest(req)
    ? tenantMaterials.filter((material: any) => teacherCanUseLearningMaterialPayload(req, material))
    : tenantMaterials;
  return visible.map((material: any) => protectLearningMaterialAssetDelivery(material));
}

function resolveLearningMaterialForRequest(req: any, materialId: any): { material: any | null; index: number; ambiguous: boolean } {
  const matches: number[] = [];
  for (let i = 0; i < (lessonPlans || []).length; i++) {
    if (String((lessonPlans as any[])[i]?.id || '') === String(materialId) &&
        isLearningMaterialRecord((lessonPlans as any[])[i]) &&
        lessonPlanBelongsToRequest((lessonPlans as any[])[i], req)) {
      matches.push(i);
    }
  }
  if (matches.length === 1) return { material: (lessonPlans as any[])[matches[0]], index: matches[0], ambiguous: false };
  if (matches.length > 1) return { material: null, index: -1, ambiguous: true };
  return { material: null, index: -1, ambiguous: false };
}

function sanitizeLearningBlocks(rawBlocks: any): any[] {
  const source = Array.isArray(rawBlocks) ? rawBlocks : [];
  const blocks: any[] = [];
  for (const raw of source.slice(0, 24)) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) continue;
    const type = String(raw.type || 'text').toLowerCase();
    if (type === 'text') {
      const content = String(raw.content || raw.text || '').slice(0, 120000);
      if (content.trim()) blocks.push({ type: 'text', content });
      continue;
    }
    if (type === 'video' || type === 'link') {
      const url = String(raw.url || '').trim().slice(0, 2048);
      if (/^https?:\/\//i.test(url)) blocks.push({ type, url });
      continue;
    }
    if (type === 'image' || type === 'pdf') {
      let url = String(raw.url || '').trim().slice(0, 2048);
      let driveFileId = String(raw.driveFileId || '').trim();
      // Preserve Google Drive PDF references. Older saved materials may have stored
      // the protected proxy URL in block.url; normalize that legacy shape back to
      // driveFileId so the browser can hydrate the PDF after authentication.
      if (type === 'pdf' && !driveFileId && url) {
        try {
          const parsed = new URL(url, 'https://madrasah.local');
          if (parsed.pathname === '/api/learning-assets/drive-pdf') {
            driveFileId = String(parsed.searchParams.get('id') || '').trim();
            if (driveFileId) url = '';
          } else if (parsed.pathname === '/api/learning-assets/inline-pdf') {
            const legacyUrl = String(parsed.searchParams.get('url') || '').trim();
            if (isTrustedLearningAssetUrl(legacyUrl)) url = legacyUrl;
          }
        } catch (_) {}
      }
      if (type === 'pdf' && driveFileId && !/^[A-Za-z0-9_-]{10,200}$/.test(driveFileId)) {
        driveFileId = '';
      }
      if (type === 'pdf' && driveFileId) {
        const fallbackName = 'Materi PDF';
        const name = sanitizeLearningAssetName(raw.name || raw.alt || raw.caption, fallbackName);
        blocks.push({ type, url: '', driveFileId, name });
        continue;
      }
      if (!isTrustedLearningAssetUrl(url)) continue;
      const fallbackName = type === 'pdf' ? 'Materi PDF' : 'Gambar materi';
      const name = sanitizeLearningAssetName(raw.name || raw.alt || raw.caption, fallbackName);
      blocks.push({ type, url, driveFileId: '', name });
      continue;
    }
  }
  return blocks;
}

function sanitizeLearningMaterialForStudent(material: any): any {
  const {
    identitasModul, kompetensiAwal, profilPancasila, saranaPrasarana, targetPeserta,
    modelPembelajaran, tujuanPembelajaran, pemahamanBermakna, pertanyaanPemantik,
    persiapanPembelajaran, kegiatanPembelajaran, asesmen, pengayaanRemedial, lkpd,
    lembarKerja, glosarium, daftarPustaka, teacherNotes, internalNotes, ...safe
  } = material || {};
  return {
    ...safe,
    recordType: 'learning_material',
    status: 'published',
    blocks: protectLearningPdfDeliveryBlocks(sanitizeLearningBlocks(safe.blocks))
  };
}

function learningEngagementPolicy(material: any): { minActiveSeconds: number; requireAllBlocks: boolean } {
  const policy = material?.engagementPolicy && typeof material.engagementPolicy === 'object' && !Array.isArray(material.engagementPolicy)
    ? material.engagementPolicy
    : {};
  const minActiveSeconds = Math.max(0, Math.min(3600, Math.floor(Number(policy.minActiveSeconds ?? material?.minActiveSeconds ?? 45) || 0)));
  return {
    minActiveSeconds,
    requireAllBlocks: policy.requireAllBlocks === false ? false : true
  };
}

function learningBlockIds(material: any): string[] {
  // Match the exact block list/IDs exposed to students after sanitization.
  // sanitizeLearningBlocks intentionally drops raw IDs and unsupported block types,
  // so completion checks must use the same canonical block_N identifiers.
  const blocks = sanitizeLearningBlocks(material?.blocks);
  return blocks.map((_block: any, index: number) => `block_${index + 1}`);
}

function sanitizeLearningMaterialMutation(req: any, raw: any, existing: any = {}): any {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Payload materi tidak valid.');
  }
  const title = String(raw.title || existing.title || '').trim().slice(0, 240);
  if (!title) throw new Error('Judul materi wajib diisi.');
  const statusRaw = String(raw.status || existing.status || 'draft').toLowerCase();
  const status = statusRaw === 'published' ? 'published' : 'draft';
  const requestedClasses = Array.isArray(raw.classes)
    ? raw.classes
    : (Array.isArray(existing.classes) ? existing.classes : [raw.classId ?? raw.class_id ?? existing.classId].filter(Boolean));
  let classes = Array.from(new Set(
    requestedClasses.map((value: any) => String(value).trim().slice(0, 160)).filter(Boolean)
  )).slice(0, 80);
  if (classes.some((value: string) => value.toUpperCase() === 'ALL')) classes = ['ALL'];
  if (classes.length === 0) classes = ['ALL'];
  const classId = classes[0];
  const subjectId = String(raw.subjectId ?? raw.subject ?? existing.subjectId ?? '').trim().slice(0, 160);
  const lkpdId = String(raw.lkpdId || '').trim().slice(0, 256);
  const examId = String(raw.examId || '').trim().slice(0, 256);
  const rawPolicy = raw.engagementPolicy && typeof raw.engagementPolicy === 'object' && !Array.isArray(raw.engagementPolicy)
    ? raw.engagementPolicy
    : {};
  const existingPolicy = existing.engagementPolicy && typeof existing.engagementPolicy === 'object' && !Array.isArray(existing.engagementPolicy)
    ? existing.engagementPolicy
    : {};
  const engagementPolicy = {
    minActiveSeconds: Math.max(0, Math.min(3600, Math.floor(Number(rawPolicy.minActiveSeconds ?? existingPolicy.minActiveSeconds ?? 45) || 0))),
    requireAllBlocks: rawPolicy.requireAllBlocks === false ? false : true
  };

  if (isTeacherRequest(req) && !teacherCanUseLearningMaterialPayload(req, { ...existing, ...raw, subjectId })) {
    throw new Error('Guru hanya dapat membuat materi untuk mata pelajaran yang diampu.');
  }
  if (lkpdId) {
    const linkedLkpd = (lkpdList || []).find((item: any) => String(item.id) === lkpdId && isItemForCurrentMadrasah(item, req));
    if (!linkedLkpd) throw new Error('LKPD tertaut tidak ditemukan pada madrasah ini.');
    if (isTeacherRequest(req) && !teacherCanUseLkpdPayload(req, linkedLkpd)) {
      throw new Error('Guru hanya dapat menautkan LKPD mata pelajaran yang diampu.');
    }
  }
  if (examId) {
    const linkedExam = (exams || []).find((item: any) => String(item.id) === examId && isItemForCurrentMadrasah(item, req));
    if (!linkedExam) throw new Error('Asesmen/CBT tertaut tidak ditemukan pada madrasah ini.');
    if (isTeacherRequest(req) && !teacherCanUseExamPayload(req, linkedExam)) {
      throw new Error('Guru hanya dapat menautkan asesmen mata pelajaran/bank soal yang diampu.');
    }
  }

  return tagNewRecord({
    ...existing,
    id: String(raw.id || existing.id || ('MAT_' + Date.now() + '_' + crypto.randomBytes(4).toString('hex'))).slice(0, 256),
    recordType: 'learning_material',
    type: 'learning_material',
    title,
    topic: String(raw.topic ?? existing.topic ?? '').trim().slice(0, 500),
    subjectId,
    subjectName: String(raw.subjectName ?? existing.subjectName ?? '').trim().slice(0, 240),
    classId,
    classes,
    blocks: sanitizeLearningBlocks(raw.blocks || existing.blocks || []),
    lkpdId,
    examId,
    // The prerequisite gate is attached to a concrete CBT schedule, never to an assessment/template.
    // For legacy materials, the old examId points to the schedule record used by this app.
    scheduleId: String(raw.scheduleId ?? existing.scheduleId ?? raw.examId ?? existing.examId ?? '').trim().slice(0, 256),
    engagementPolicy,
    // Opt-in companion material display; legacy records stay sequential.
    learningDisplayMode: String(raw.learningDisplayMode ?? existing.learningDisplayMode ?? 'sequential') === 'split' ? 'split' : 'sequential',
    // Explicit teacher opt-in for open-book practice; legacy materials remain closed-book.
    allowExamReference: raw.allowExamReference === undefined ? existing.allowExamReference === true : raw.allowExamReference === true,
    prerequisiteMaterialIds: Array.isArray(raw.prerequisiteMaterialIds)
      ? raw.prerequisiteMaterialIds.map((value: any) => String(value).trim().slice(0, 256)).filter(Boolean).slice(0, 20)
      : (Array.isArray(existing.prerequisiteMaterialIds) ? existing.prerequisiteMaterialIds : []),
    requiresCompletionForLinks: raw.requiresCompletionForLinks === false ? false : true,
    status,
    teacherId: String((req as any).user?.id || raw.teacherId || existing.teacherId || '').slice(0, 160),
    updatedAt: new Date().toISOString(),
    createdAt: existing.createdAt || new Date().toISOString()
  }, req);
}

function learningProgressKey(req: any, studentId: any, materialId: any): string {
  const tenant = canonicalRealtimeTenant(getRequestMadrasahId(req) || req?.user?.madrasahId || req?.user?.madrasahSlug || 'default');
  return `learningv1::${encodeExamStatePart(tenant)}::${encodeExamStatePart(studentId)}::${encodeExamStatePart(materialId)}`;
}

function learningProgressForRequest(req: any): any[] {
  return (learningProgress || []).filter((item: any) => isItemForCurrentMadrasah(item, req));
}

function effectiveSettingsForRequest(req: any): any {
  const base = globalSettingsBase();
  if (!isOnlineMode) return base;
  const scoped = tenantConfigValue(appSettings?.__tenantScopedSettingsV1, req, {}, 'settings');
  if (!scoped || typeof scoped !== 'object' || Array.isArray(scoped)) return base;
  return { ...base, ...scoped };
}

// Aggregated All Data endpoint for super fast loading
app.get("/api/all-data", requireAuth, (req, res) => {
  res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
  const authUser = (req as any).user;
  const mId = getRequestMadrasahId(req);
  
  // Strict Server-Side Role Resolution (Never trust unauthenticated role claims)
  const isTeacherOrAdmin = Boolean(authUser && (
    authUser.role === 'teacher' || authUser.role === 'guru' ||
    authUser.role === 'admin' || authUser.role === 'bos' || authUser.role === 'superadmin'
  ));
  const isStudent = !isTeacherOrAdmin;

  let filteredTeachers = teachers;
  let filteredStudents = students;
  let filteredClasses = classes;
  let filteredSubjects = subjects;
  let filteredAttendance = attendance;
  let filteredQGroups = questionBankGroups;
  let filteredQuestions = questions;
  let filteredSchedules = schedules;
  let filteredExams = exams;
  let filteredLkpds = lkpdList;
  let filteredGrades = grades;
  let filteredRooms = rooms;
  let filteredJournals = journals;
  let filteredLessonPlans = lessonPlans;
  let filteredGeneratedExams = generatedExams;
  let filteredImportGroups = importGroups || [];
  let filteredLearningProgress = learningProgress || [];

  if (mId && mId !== 'default' && mId !== 'BOSS') {
    const matchM = madrasahs.find(m => String(m.id) === mId || String(m.slug) === mId);
    const targetId = matchM ? matchM.id : mId;
    const targetSlug = matchM ? matchM.slug : mId;

    const matchesFilter = (item: any) => {
      const imId = String(item.madrasahId || '').trim();
      const imSlug = String(item.madrasahSlug || '').trim();
      if (!imId && !imSlug) {
        return false; // New registered madrasah starts empty, default/un-tagged items belong to main school
      }
      return imId === targetId || imSlug === targetSlug || imId === targetSlug || imSlug === targetId;
    };

    filteredTeachers = teachers.filter(matchesFilter);
    filteredStudents = students.filter(matchesFilter);
    filteredClasses = classes.filter(matchesFilter);
    filteredSubjects = subjects.filter(matchesFilter);
    filteredAttendance = attendance.filter(matchesFilter);
    filteredQGroups = questionBankGroups.filter(matchesFilter);
    filteredQuestions = questions.filter(matchesFilter);
    filteredSchedules = schedules.filter(matchesFilter);
    filteredExams = exams.filter(matchesFilter);
    filteredLkpds = lkpdList.filter(matchesFilter);
    filteredGrades = grades.filter(matchesFilter);
    filteredRooms = rooms.filter(matchesFilter);
    filteredJournals = journals.filter(matchesFilter);
    filteredLessonPlans = lessonPlans.filter(matchesFilter);
    filteredGeneratedExams = generatedExams.filter(matchesFilter);
    filteredImportGroups = (importGroups || []).filter(matchesFilter);
    filteredLearningProgress = (learningProgress || []).filter(matchesFilter);
  } else {
    const defaultM = madrasahs.find(m => m.id === 'default' || m.slug === 'default') || madrasahs[0];
    const defId = defaultM ? defaultM.id : 'default';
    const defSlug = defaultM ? defaultM.slug : 'default';

    const defaultFilter = (item: any) => {
      const imId = String(item.madrasahId || 'default').trim();
      const imSlug = String(item.madrasahSlug || 'default').trim();
      return imId === 'default' || imId === defId || imId === defSlug || imSlug === 'default' || imSlug === defSlug || imSlug === defId || (!item.madrasahId && !item.madrasahSlug);
    };

    filteredTeachers = teachers.filter(defaultFilter);
    filteredStudents = students.filter(defaultFilter);
    filteredClasses = classes.filter(defaultFilter);
    filteredSubjects = subjects.filter(defaultFilter);
    filteredAttendance = attendance.filter(defaultFilter);
    filteredQGroups = questionBankGroups.filter(defaultFilter);
    filteredQuestions = questions.filter(defaultFilter);
    filteredSchedules = schedules.filter(defaultFilter);
    filteredExams = exams.filter(defaultFilter);
    filteredLkpds = lkpdList.filter(defaultFilter);
    filteredGrades = grades.filter(defaultFilter);
    filteredRooms = rooms.filter(defaultFilter);
    filteredJournals = journals.filter(defaultFilter);
    filteredLessonPlans = lessonPlans.filter(defaultFilter);
    filteredGeneratedExams = generatedExams.filter(defaultFilter);
    filteredImportGroups = (importGroups || []).filter(defaultFilter);
    filteredLearningProgress = (learningProgress || []).filter(defaultFilter);
  }

  filteredLessonPlans = filterLessonPlansForRequest(req);

  const sortedStudents = [...filteredStudents].sort((a: any, b: any) => {
    const nameA = String(a.name || '').trim().toLowerCase();
    const nameB = String(b.name || '').trim().toLowerCase();
    if (nameA !== nameB) {
      return nameA.localeCompare(nameB, 'id', { sensitivity: 'base' });
    }
    const nisA = String(a.nis || a.no_urut || a.id || '').trim();
    const nisB = String(b.nis || b.no_urut || b.id || '').trim();
    return nisA.localeCompare(nisB, undefined, { numeric: true, sensitivity: 'base' });
  });

  const actorRole = String(authUser?.role || '').toLowerCase();
  if (actorRole === 'teacher' || actorRole === 'guru') {
    filteredQGroups = filteredQGroups.filter((group: any) => questionBankGroupAllowedForTeacher(req, group));
    filteredQuestions = filteredQuestions.filter((question: any) => questionAllowedForTeacher(req, question));
    filteredExams = filteredExams.filter((exam: any) => teacherCanUseExamPayload(req, exam));
    filteredLessonPlans = filteredLessonPlans.filter((material: any) =>
      !isLearningMaterialRecord(material) || teacherCanUseLearningMaterialPayload(req, material)
    );
    const allowedLearningMaterialIds = new Set(filteredLessonPlans.filter(isLearningMaterialRecord).map((material: any) => String(material.id)));
    filteredLearningProgress = filteredLearningProgress.filter((progress: any) =>
      allowedLearningMaterialIds.has(String(progress.materialId || ''))
    );
  }

  // Students only receive the minimum data required by their own UI.
  // Question-bank contents and teacher-only academic/admin datasets stay server-side.
  const studentRole = actorRole;
  const isClassLeader = studentRole === 'class_leader' || studentRole === 'ketua_kelas';
  if (isStudent) {
    const ownId = String(authUser?.id || '');
    const selfStudent = filteredStudents.find((st: any) => String(st.id) === ownId);
    const ownClassId = String(selfStudent?.classId || selfStudent?.class_id || '');

    filteredQuestions = [];
    filteredQGroups = [];
    filteredExams = selfStudent
      ? filteredExams.filter((exam: any) => studentCanAccessExam(selfStudent, exam)).map(sanitizeExamForStudent)
      : [];
    filteredLkpds = selfStudent
      ? filteredLkpds.filter((lkpd: any) => studentCanAccessLkpd(selfStudent, lkpd)).map((lkpd: any) => sanitizeLkpdForStudent(lkpd, ownId))
      : [];

    if (isClassLeader && ownClassId) {
      filteredStudents = filteredStudents.filter((st: any) =>
        String(st.classId || st.class_id || '') === ownClassId
      );
      filteredAttendance = filteredAttendance.filter((item: any) =>
        String(item.classId || '') === ownClassId
      );
    } else {
      filteredStudents = filteredStudents.filter((st: any) => String(st.id) === ownId);
      filteredAttendance = filteredAttendance.filter((item: any) => String(item.studentId || '') === ownId);
    }

    filteredGrades = filteredGrades.filter((item: any) =>
      String(item.studentId || item.student_id || '') === ownId
    );
    filteredTeachers = filteredTeachers.map(sanitizeTeacherForStudent).filter(Boolean);
    filteredStudents = filteredStudents.map(sanitizeStudentPeerProfile).filter(Boolean);
    filteredJournals = [];
    filteredGeneratedExams = [];
    filteredLessonPlans = filteredLessonPlans
      .filter((material: any) => studentCanAccessLearningMaterial(selfStudent, material))
      .map(sanitizeLearningMaterialForStudent);
    filteredLearningProgress = filteredLearningProgress.filter((item: any) => String(item.studentId || '') === ownId);
  }

  // Sanitasi sensitif (hilangkan password dan adminPass)
  const sanitizedTeachers = filteredTeachers.map(({ password, ...rest }: any) => ({
    ...rest,
    photo: normalizePhotoReferenceForClient(rest.photo),
    photoHistory: normalizePhotoHistoryForClient(rest.photoHistory)
  }));
  const exposeStudentPasswords = actorRole === 'admin';
  const sanitizedStudents = (isStudent ? filteredStudents : sortedStudents).map((st: any) => {
    const rest = sanitizeStudentForClient(st, exposeStudentPasswords);
    return {
      ...rest,
      photo: normalizePhotoReferenceForClient(rest.photo),
      photoHistory: normalizePhotoHistoryForClient(rest.photoHistory)
    };
  });
  const isBosUser = Boolean(authUser && (authUser.role === 'bos' || authUser.role === 'superadmin'));
  const visibleMadrasahs = isBosUser
    ? (madrasahs || [])
    : (madrasahs || []).filter((m: any) => {
        const requestId = String(mId || authUser?.madrasahId || authUser?.madrasahSlug || 'default');
        return String(m.id) === requestId || String(m.slug) === requestId;
      });
  const sanitizedMadrasahs = visibleMadrasahs
    .map(isBosUser ? sanitizeMadrasahAdminView : sanitizeMadrasahMemberView)
    .filter(Boolean);
  const sanitizedSettings = sanitizeSettingsForClient(effectiveSettingsForRequest(req));
  if (sanitizedSettings && typeof sanitizedSettings === 'object') {
    sanitizedSettings.livekitConfigured = resolveLiveKitRuntimeConfig().configured;
  }

  res.json({
    success: true,
    teachers: sanitizedTeachers,
    students: sanitizedStudents,
    classes: filteredClasses,
    subjects: filteredSubjects,
    attendance: filteredAttendance,
    questionBankGroups: filteredQGroups,
    questions: filteredQuestions,
    schedules: filteredSchedules,
    savedRosters: Array.isArray(savedRosters) ? filterByMadrasah(savedRosters, req) : savedRosters,
    timeSlots: Array.isArray(timeSlots) ? filterByMadrasah(timeSlots, req) : [],
    kbmDuration: tenantConfigValue(kbmDuration, req, 40, 'kbmDuration'),
    exams: filteredExams,
    lkpdList: filteredLkpds,
    rooms: filteredRooms,
    journals: filteredJournals,
    gradeCategories: tenantConfigValue(gradeCategories, req, [], 'gradeCategories'),
    calendarEvents: filterByMadrasah(calendarEvents || [], req),
    generatedExams: filteredGeneratedExams,
    settings: sanitizedSettings,
    lessonPlans: filteredLessonPlans,
    learningProgress: filteredLearningProgress,
    importGroups: isStudent ? [] : filteredImportGroups,
    grades: filteredGrades,
    teacherAttendance: isStudent ? [] : filterByMadrasah(teacherAttendance || [], req),
    customGradeColumns: isStudent ? {} : tenantConfigValue(customGradeColumns, req, {}, 'customGradeColumns'),
    // ChildGuard APK integration is retired. Legacy persisted keys remain for
    // backup compatibility but are intentionally not exposed to active clients.
    madrasahs: sanitizedMadrasahs,
    tokenRequests: isStudent ? [] : (isBosUser ? tokenRequests : filterByMadrasah(tokenRequests || [], req)),
    cbtTokenPrice,
    eduGames: getGamesForRequest(req),
    gameAttempts: isStudent
      ? filterByMadrasah(gameAttempts || [], req).filter((attempt: any) => String(attempt?.studentId || '') === String(authUser?.id || ''))
      : filterByMadrasah(gameAttempts || [], req)
  });
});

function findStudentForRequest(req: any, identifier: any): { student: any | null; ambiguous: boolean } {
  const raw = String(identifier || '');
  const matches = (students || []).filter((item: any) =>
    String(item.id) === raw || String(item.nis || '') === raw
  );
  const owned = matches.filter((item: any) => isItemForCurrentMadrasah(item, req));
  if (owned.length === 1) return { student: owned[0], ambiguous: false };
  if (owned.length > 1) return { student: null, ambiguous: true };
  const role = String((req as any)?.user?.role || '').toLowerCase();
  const isBoss = role === 'bos' || role === 'superadmin';
  if (isBoss && matches.length === 1) return { student: matches[0], ambiguous: false };
  return { student: null, ambiguous: isBoss && matches.length > 1 };
}

