app.get("/api/db-status", requireAuth, requireRole(['admin', 'bos', 'superadmin']), async (req, res) => {
  const status: any = {
    connected: false,
    mode: storageMode,
    sql: {
      connected: false,
      configured: false,
      message: "Belum diperiksa.",
      details: "",
      capacity: null
    },
    firebase: {
      connected: false,
      configured: false,
      message: "Belum diperiksa.",
      details: ""
    },
    json: {
      connected: false,
      configured: false,
      message: "Belum diperiksa.",
      details: ""
    },
    cloudinary: {
      connected: false,
      configured: false,
      message: "Belum diperiksa.",
      details: "",
      capacity: null
    }
  };

  // 1. Check SQL (PostgreSQL/Cloud SQL)
  try {
    const hasCredentials = Boolean(
      (process.env.SQL_USER || process.env.PGUSER || process.env.SQL_ADMIN_USER) &&
      (process.env.SQL_PASSWORD || process.env.PGPASSWORD || process.env.SQL_ADMIN_PASSWORD)
    );
    const hasSocketHint = Boolean(
      process.env.SQL_HOST ||
      process.env.CLOUD_SQL_CONNECTION_NAME ||
      process.env.INSTANCE_CONNECTION_NAME ||
      fs.existsSync('/cloudsql') ||
      fs.existsSync('/app/cloudsql')
    );
    const hasEnv = Boolean(hasCredentials && hasSocketHint);
    if (!hasEnv) {
      status.sql.message = "Konfigurasi Cloud SQL belum lengkap: credential PostgreSQL atau mount socket Cloud SQL belum tersedia.";
    } else {
      status.sql.configured = true;
      if (dbInitPromise) {
        await dbInitPromise;
      }
      if (!pool || activeDbSource === "NONE" || isDbQuotaExceeded) {
        isDbQuotaExceeded = false;
        dbInitPromise = determineAndInitPool();
        await dbInitPromise;
      }
      if (!pool) {
        status.sql.message = "Gagal menginisialisasi database pool.";
      } else {
        const queryPromise = pool.query("SELECT 1");
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error("Koneksi SQL timeout (3 detik).")), 3000)
        );
        await Promise.race([queryPromise, timeoutPromise]);
        
        let keysCount = 0;
        let databaseBytes: number | null = null;
        let databaseName = '';
        try {
          const testResult = await pool.query("SELECT COUNT(*) FROM app_store");
          keysCount = parseInt(testResult.rows[0].count, 10);
          status.sql.details = `Tabel app_store aktif dengan ${keysCount} baris record.`;
        } catch (e: any) {
          status.sql.details = "Koneksi berhasil, tetapi tabel app_store belum terbentuk atau tidak terbaca.";
        }
        try {
          const sizeResult = await pool.query(
            "SELECT current_database() AS database_name, pg_database_size(current_database())::bigint AS database_bytes"
          );
          databaseName = String(sizeResult.rows?.[0]?.database_name || '');
          const parsedBytes = Number(sizeResult.rows?.[0]?.database_bytes);
          if (Number.isFinite(parsedBytes) && parsedBytes >= 0) databaseBytes = parsedBytes;
        } catch (_) {}

        let platformCapacity: any = { available: false };
        if (isOnlineMode) {
          try {
            platformCapacity = await readCloudSqlPlatformCapacity();
          } catch (capacityErr: any) {
            platformCapacity = {
              available: false,
              health: 'unknown',
              note: `Metrik platform tidak dapat dibaca: ${capacityErr?.message || capacityErr}`
            };
          }
        }
        status.sql.capacity = {
          databaseName,
          databaseBytes,
          databaseFormatted: databaseBytes !== null ? storageFormatBytes(databaseBytes) : '',
          ...platformCapacity,
          note: platformCapacity?.note || platformCapacity?.reason || ''
        };
        status.sql.connected = true;
        status.sql.message = `Terhubung sukses ke ${activeDbSource}!`;
      }
    }
  } catch (err: any) {
    status.sql.connected = false;
    status.sql.message = "Gagal terhubung ke PostgreSQL / Cloud SQL.";
    status.sql.details = err.message || String(err);
  }

  // 2. Firebase Firestore is intentionally disabled in the current architecture.
  // Do not probe it as a health dependency.
  status.firebase.configured = false;
  status.firebase.connected = false;
  status.firebase.skipped = true;
  status.firebase.message = "Dinonaktifkan sesuai arsitektur aplikasi.";
  status.firebase.details = "";

  // 3. Local JSON is only a health dependency in OFFLINE mode.
  if (isOfflineMode) {
    try {
      const exists = fs.existsSync(LOCAL_STORE_FILE);
      if (!exists) {
        status.json.message = "File local_store.json tidak ditemukan.";
      } else {
        status.json.configured = true;
        const raw = fs.readFileSync(LOCAL_STORE_FILE, "utf-8");
        const parsed = JSON.parse(decryptLocalStore(raw));
        const keysCount = Object.keys(parsed || {}).length;
        status.json.connected = true;
        status.json.message = "File lokal local_store.json terbaca dan valid!";
        status.json.details = `Memiliki ${keysCount} kategori modul data tersimpan.`;
      }
    } catch (err: any) {
      status.json.connected = false;
      status.json.message = "File lokal local_store.json rusak atau gagal dibaca.";
      status.json.details = err.message || String(err);
    }
  } else {
    status.json.configured = false;
    status.json.connected = false;
    status.json.skipped = true;
    status.json.message = "Tidak digunakan pada mode online; Cloud SQL adalah source of truth.";
    status.json.details = "";
  }

  // 4. Check Cloudinary
  try {
    if (!process.env.CLOUDINARY_CLOUD_NAME) {
      status.cloudinary.message = "Variabel lingkungan CLOUDINARY_CLOUD_NAME tidak ditemukan.";
    } else {
      status.cloudinary.configured = true;
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error("Koneksi Cloudinary timeout (3 detik).")), 3000)
      );
      await Promise.race([cloudinary.api.ping(), timeoutPromise]);
      status.cloudinary.connected = true;
      status.cloudinary.message = "Terhubung sukses ke Cloudinary!";
      let capacityDetails = '';
      try {
        const usage: any = await Promise.race([
          cloudinary.api.usage(),
          new Promise((_, reject) => setTimeout(() => reject(new Error('Cloudinary usage timeout')), 3500))
        ]);
        const storageBytes = Number(usage?.storage?.usage ?? usage?.storage?.used ?? 0);
        const creditUsed = Number(usage?.credits?.usage ?? usage?.credits?.used ?? 0);
        const creditLimit = Number(usage?.credits?.limit ?? 0);
        const reportedPercent = Number(usage?.credits?.used_percent);
        const creditPercent = creditLimit > 0 && Number.isFinite(creditUsed)
          ? (creditUsed / creditLimit) * 100
          : (Number.isFinite(reportedPercent) ? reportedPercent : null);
        const creditRemaining =
          creditLimit > 0 && Number.isFinite(creditUsed) ? Math.max(0, creditLimit - creditUsed) : null;
        const storageCredits = Number(usage?.storage?.credits_usage);
        const bandwidthCredits = Number(usage?.bandwidth?.credits_usage);
        const transformationCredits = Number(usage?.transformations?.credits_usage);

        status.cloudinary.capacity = {
          available: true,
          plan: String(usage?.plan || usage?.plan_name || ''),
          storageBytes: Number.isFinite(storageBytes) ? storageBytes : null,
          storageFormatted: Number.isFinite(storageBytes) ? storageFormatBytes(storageBytes) : '',
          creditUsed: Number.isFinite(creditUsed) ? creditUsed : null,
          creditLimit: Number.isFinite(creditLimit) && creditLimit > 0 ? creditLimit : null,
          creditRemaining,
          creditPercent,
          health: storageHealthLevel(creditPercent),
          storageCredits: Number.isFinite(storageCredits) ? storageCredits : null,
          bandwidthCredits: Number.isFinite(bandwidthCredits) ? bandwidthCredits : null,
          transformationCredits: Number.isFinite(transformationCredits) ? transformationCredits : null
        };

        if (Number.isFinite(storageBytes)) {
          capacityDetails = ` Storage aktual: ${storageFormatBytes(storageBytes)}.`;
        }
        if (creditLimit > 0 && Number.isFinite(creditUsed)) {
          capacityDetails += ` Kuota credit: ${creditUsed.toFixed(2)} dari ${creditLimit.toFixed(2)} terpakai; ${Math.max(0, creditLimit - creditUsed).toFixed(2)} tersisa.`;
        }
      } catch (usageErr: any) {
        status.cloudinary.capacity = {
          available: false,
          health: 'unknown',
          note: usageErr?.message || String(usageErr)
        };
        console.warn('[Cloudinary Status] Kapasitas tidak dapat dibaca:', usageErr?.message || usageErr);
      }
      status.cloudinary.details = `Penyimpanan foto Cloudinary (${process.env.CLOUDINARY_CLOUD_NAME}) aktif. ${Object.keys(photoCloudinaryMap).length} entri mapping foto tersedia.${capacityDetails}`;
    }
  } catch (err: any) {
    status.cloudinary.connected = false;
    status.cloudinary.message = "Gagal terhubung ke Cloudinary.";
    status.cloudinary.details = err.message || String(err);
  }

  // Mode-aware connection logic: only authoritative services determine health.
  if (isOfflineMode) {
    status.connected = Boolean(status.sql.connected && status.json.connected);
    if (status.connected) {
      status.message = "Sistem Luring (Offline) Aktif: PostgreSQL dan local_store.json terhubung.";
    } else {
      const failures = [];
      if (!status.sql.connected) failures.push("PostgreSQL lokal");
      if (!status.json.connected) failures.push("Local JSON");
      status.message = `Sistem Offline bermasalah pada: ${failures.join(', ')}.`;
    }
  } else {
    status.connected = Boolean(status.sql.connected && status.cloudinary.connected);
    if (status.connected) {
      status.message = "Sistem Online Aktif: Cloud SQL dan Cloudinary terhubung.";
    } else {
      const failures = [];
      if (!status.sql.connected) failures.push("PostgreSQL/Cloud SQL");
      if (!status.cloudinary.connected) failures.push("Cloudinary");
      status.message = `Sistem Online bermasalah pada: ${failures.join(', ')}.`;
    }
  }

  res.json(status);
});

// 1b. Cloudinary On-Demand Sync Endpoint
app.post("/api/cloudinary/sync", async (req, res) => {
  try {
    const result = await syncAllPhotosToCloudinary();
    res.json({
      success: true,
      message: `Sinkronisasi Cloudinary berhasil! Aset aktual: ${result.totalCloudinary}; entri mapping: ${result.mapped}.`,
      result
    });
  } catch (err: any) {
    res.status(500).json({ success: false, message: safeServerError(err) });
  }
});


