function isLivecamAuditPath(pathname:string):boolean {
  const p=String(pathname||'').toLowerCase();
  return ['/api/exam/signaling','/api/exam/livecam','/api/exam/livekit-token','/api/livecam','/spotlight'].some(part=>p.includes(part));
}
function shouldSkipOpsAudit(pathname:string):boolean {
  const p=String(pathname||'').toLowerCase();
  if (isLivecamAuditPath(p)) return true;
  // CBT attempt mutations are latency-sensitive and already persist their own authoritative state.
  // Never enqueue them behind the Operations audit write chain; doing so turns every answer into
  // an additional full auditLogs persistence and can saturate Cloud SQL under exam bursts.
  if (p === '/api/exam/attempt' || p.startsWith('/api/exam/attempt/')) return true;
  if (/\/api\/games\/[^/]+\/(?:submit|check)$/.test(p)) return true;
  if (p.includes('/api/chat') || (p.includes('/api/ops/notifications/') && p.endsWith('/read'))) return true;
  return ['/api/exam-monitoring-state','/api/realtime','/api/signaling','/api/exam-answer','/api/exam-progress','/api/exam-heartbeat','/heartbeat'].some(part=>p.includes(part));
}
let opsAuditWriteChain: Promise<any> = Promise.resolve();
async function saveOpsState(key:string,value:any) {
  updateMemoryKey(key,value);
  if(isOnlineMode){
    if(dbInitPromise) await dbInitPromise;
    if(!pool || isDbQuotaExceeded) throw new Error('ONLINE_DATABASE_UNAVAILABLE: cannot persist '+key);
    await dbWriteQueue.run('ops::'+key, async()=>{
      await pool.query(
        'INSERT INTO app_store (key, value) VALUES ($1, $2) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value',
        [key, JSON.stringify(value)]
      );
    });
    return;
  }
  const store=readLocalStore();
  store[key]=value;
  writeLocalStore(store);
  if(pool && !isDbQuotaExceeded) scheduleDbWrite(key);
}

async function appendOpsAudit(req:any,statusCode:number,durationMs=0) {
  const user=req?.user || getAuthUser(req); if(!user) return;
  const row={id:'AUD_'+Date.now()+'_'+crypto.randomBytes(3).toString('hex'),at:new Date().toISOString(),madrasahId:opsTenant(req),userId:String(user.id||''),username:String(user.username||user.name||''),role:String(user.role||'').toLowerCase(),method:String(req.method||'').toUpperCase(),path:String(req.path||'').slice(0,300),statusCode:Number(statusCode||0),durationMs:Math.max(0,Number(durationMs||0))};
  auditLogs.unshift(row); if(auditLogs.length>1200) auditLogs.length=1200;
  opsAuditWriteChain=opsAuditWriteChain.then(()=>saveOpsState('auditLogs',auditLogs)).catch(()=>{});
  await opsAuditWriteChain;
}
