  if(isOnlineMode&&(!pool||isDbQuotaExceeded)) rows.push({id:'GEN_DB',madrasahId:tenant,type:'critical',title:'Database perlu perhatian',message:'Cloud SQL belum sehat atau tidak tersedia.',targetRoles:['admin','bos','superadmin'],createdAt:now,readBy:[],source:'health',targetRoute:'ops_health'});
