  const tenantStudents=filterByMadrasah(students||[],req)||[], ids=new Set(tenantStudents.map((s:any)=>String(s.id))); let blocked=0;
  for(const [key,val] of Object.entries(blockedStudents||{})){if(!val)continue;for(const id of ids){if(String(key).startsWith(String(id)+'_')){blocked++;break;}}}
  if(blocked>0) rows.push({id:'GEN_BLK_'+tenant,madrasahId:tenant,type:'warning',title:'Peserta CBT terblokir',message:String(blocked)+' attempt perlu pemeriksaan.',targetRoles:['admin','teacher','guru','bos','superadmin'],createdAt:now,readBy:[],source:'cbt',targetRoute:'exam_evaluation'});
  const cfg=mergedOpsConfig(req), threshold=Math.max(0,Number(cfg.tokenLowThreshold||5)), m=(madrasahs||[]).find((x:any)=>canonicalRealtimeTenant(x?.id||x?.slug||'default')===tenant);
  if(m&&Number(m.cbtTokenBalance||0)<=threshold&&['admin','teacher','guru','bos','superadmin'].includes(role)) rows.push({id:'GEN_TKN_'+tenant,madrasahId:tenant,type:'warning',title:'Token CBT hampir habis',message:'Saldo token saat ini '+Number(m.cbtTokenBalance||0)+'.',targetRoles:['admin','teacher','guru','bos','superadmin'],createdAt:now,readBy:[],source:'token',targetRoute:'ops_health'});
