function normalizeLessonPlanRecoveryText(value: any): string {
  return String(value ?? '').normalize('NFKC').trim().replace(/\s+/g, ' ').toLowerCase();
}

function lessonPlanRecoveryTenant(req: any): { id: string; slug: string } {
  const requested = String(getRequestMadrasahId(req) || 'default').trim() || 'default';
  const match = (madrasahs || []).find((m: any) =>
    String(m?.id || '') === requested || String(m?.slug || '') === requested
  );
  const id = String(match?.id || requested || 'default').trim() || 'default';
  const slug = String(match?.slug || id).trim() || id;
  return { id, slug };
}

function deterministicLegacyRecoveryId(prefix: string, tenantId: string, legacyId: string): string {
  const digest = crypto.createHash('sha256')
    .update(`${tenantId}::${legacyId}`)
    .digest('hex')
    .slice(0, 24);
  return `${prefix}_${digest}`;
}

async function recoverLegacyLessonPlanBundle(req: any, body: any): Promise<any> {
  if (!isOnlineMode) {
    throw new Error('Recovery modul legacy ini hanya digunakan pada mode online.');
  }

  const dryRun = body?.dryRun === true;
  const incomingPlans = Array.isArray(body?.plans) ? body.plans : [];
  const incomingGroups = Array.isArray(body?.groups) ? body.groups : [];
  const targetSubjectName = String(body?.targetSubjectName || '').trim();
  const targetSubjectIdInput = String(body?.targetSubjectId || '').trim();

  if (incomingPlans.length < 1 || incomingPlans.length > 100) {
    throw new Error('Bundle recovery harus berisi 1-100 modul.');
  }
  if (incomingGroups.length < 1 || incomingGroups.length > 20) {
    throw new Error('Bundle recovery harus berisi 1-20 kelompok.');
  }

  const tenant = lessonPlanRecoveryTenant(req);
  const tenantSubjects = filterByMadrasah(subjects || [], req);
  let targetSubject: any = null;

  if (targetSubjectIdInput) {
    const matches = tenantSubjects.filter((subject: any) =>
      String(subject?.id || '') === targetSubjectIdInput ||
      String(subject?.code || '') === targetSubjectIdInput
    );
    if (matches.length === 1) targetSubject = matches[0];
    else if (matches.length > 1) throw new Error('Mapel target ambigu pada tenant aktif.');
  }

  if (!targetSubject && targetSubjectName) {
    const normalizedName = normalizeLessonPlanRecoveryText(targetSubjectName);
    const matches = tenantSubjects.filter((subject: any) =>
      normalizeLessonPlanRecoveryText(subject?.name) === normalizedName ||
      normalizeLessonPlanRecoveryText(subject?.code) === normalizedName
    );
    if (matches.length === 1) targetSubject = matches[0];
    else if (matches.length > 1) throw new Error('Nama mapel target ambigu pada tenant aktif.');
  }

  if (!targetSubject) {
    throw new Error('Mapel target recovery tidak ditemukan pada tenant aktif.');
  }

  const targetSubjectId = String(targetSubject.id || targetSubject.code || '').trim();
  const targetSubjectDisplayName = String(targetSubject.name || targetSubject.code || targetSubjectId).trim();
  if (!targetSubjectId) throw new Error('ID mapel target tidak valid.');

  const groupMap = new Map<string, any>();
  for (const rawGroup of incomingGroups) {
    if (!rawGroup || typeof rawGroup !== 'object') continue;
    const legacyGroupId = String(rawGroup.legacyGroupId || rawGroup.id || '').trim();
    const name = String(rawGroup.name || rawGroup.groupName || '').trim();
    if (!legacyGroupId || !name || legacyGroupId.length > 160 || name.length > 160) continue;

    const recoveredGroupId = deterministicLegacyRecoveryId('recgrp', tenant.id, legacyGroupId);
    groupMap.set(legacyGroupId, {
      legacyGroupId,
      recoveredGroupId,
      name,
      description: String(rawGroup.description || '').trim().slice(0, 500)
    });
  }
  if (groupMap.size === 0) throw new Error('Tidak ada kelompok recovery yang valid.');

  const stats: any = {
    dryRun,
    targetSubjectId,
    targetSubjectName: targetSubjectDisplayName,
    inputPlans: incomingPlans.length,
    inputGroups: incomingGroups.length,
    validGroups: groupMap.size,
    validPlans: 0,
    foundLegacyInDatabase: 0,
    restoredFromBundle: 0,
    alreadyRecovered: 0,
    invalidPlans: 0,
    ambiguousLegacyIds: 0,
    recoveredPlans: 0,
    recoveredGroups: groupMap.size,
    groupCounts: {} as Record<string, number>
  };

  const nextLessonPlans = Array.isArray(lessonPlans) ? [...lessonPlans] : [];
  const nextImportGroups = Array.isArray(importGroups) ? [...importGroups] : [];
  const seenLegacyIds = new Set<string>();

  for (const rawPlan of incomingPlans) {
    if (!rawPlan || typeof rawPlan !== 'object') {
      stats.invalidPlans++;
      continue;
    }
    const legacyId = String(rawPlan.legacyId || rawPlan.id || '').trim();
    const legacyGroupId = String(rawPlan.legacyGroupId || rawPlan.groupId || rawPlan.group_id || '').trim();
    const mappedGroup = groupMap.get(legacyGroupId);

    if (!legacyId || legacyId.length > 180 || !mappedGroup || seenLegacyIds.has(legacyId)) {
      stats.invalidPlans++;
      continue;
    }
    seenLegacyIds.add(legacyId);
    stats.validPlans++;
    stats.groupCounts[mappedGroup.name] = (stats.groupCounts[mappedGroup.name] || 0) + 1;

    const alreadyIndexes: number[] = [];
    const legacyIndexes: number[] = [];
    for (let i = 0; i < nextLessonPlans.length; i++) {
      const item: any = nextLessonPlans[i];
      if (!item) continue;
      if (
        String(item?.legacyRecoverySourceId || '') === legacyId &&
        isItemForCurrentMadrasah(item, req)
      ) {
        alreadyIndexes.push(i);
      }
      if (
        String(item?.id || '') === legacyId &&
        !String(item?.madrasahId || '').trim() &&
        !String(item?.madrasahSlug || '').trim()
      ) {
        legacyIndexes.push(i);
      }
    }

    if (alreadyIndexes.length > 1 || legacyIndexes.length > 1) {
      stats.ambiguousLegacyIds++;
      continue;
    }

    let base: any;
    let targetIndex = -1;
    let finalId = '';

    if (alreadyIndexes.length === 1) {
      targetIndex = alreadyIndexes[0];
      base = { ...nextLessonPlans[targetIndex] };
      finalId = String(base.id || deterministicLegacyRecoveryId('reclp', tenant.id, legacyId));
      stats.alreadyRecovered++;
    } else if (legacyIndexes.length === 1) {
      targetIndex = legacyIndexes[0];
      base = { ...nextLessonPlans[targetIndex] };
      finalId = legacyId;
      stats.foundLegacyInDatabase++;
    } else {
      base = { ...rawPlan };
      finalId = deterministicLegacyRecoveryId('reclp', tenant.id, legacyId);
      stats.restoredFromBundle++;
    }

    for (const key of ['madrasahId', 'madrasahSlug', 'madrasah_id', 'madrasah_slug', 'tenantId']) {
      delete base[key];
    }
    for (const key of LESSON_PLAN_CHILD_KEYS) {
      delete base[key];
    }

    const recovered = {
      ...base,
      id: finalId,
      subjectId: targetSubjectId,
      subjectName: targetSubjectDisplayName,
      groupId: mappedGroup.recoveredGroupId,
      groupName: mappedGroup.name,
      madrasahId: tenant.id,
      madrasahSlug: tenant.slug,
      legacyRecoverySourceId: legacyId,
      legacyRecoveryGroupId: legacyGroupId,
      __legacyMode2RecoveredV1: true
    };

    if (targetIndex >= 0) nextLessonPlans[targetIndex] = recovered;
    else nextLessonPlans.push(recovered);
    stats.recoveredPlans++;
  }

  for (const mappedGroup of groupMap.values()) {
    const idx = nextImportGroups.findIndex((group: any) =>
      String(group?.id || '') === mappedGroup.recoveredGroupId &&
      isItemForCurrentMadrasah(group, req)
    );
    const groupRecord = {
      ...(idx >= 0 ? nextImportGroups[idx] : {}),
      id: mappedGroup.recoveredGroupId,
      subjectId: targetSubjectId,
      name: mappedGroup.name,
      description: mappedGroup.description,
      madrasahId: tenant.id,
      madrasahSlug: tenant.slug,
      legacyRecoveryGroupId: mappedGroup.legacyGroupId,
      __legacyMode2RecoveredV1: true
    };
    if (idx >= 0) nextImportGroups[idx] = groupRecord;
    else nextImportGroups.push(groupRecord);
  }

  if (dryRun) return stats;

  lessonPlans = nextLessonPlans;
  importGroups = nextImportGroups;

  // Save plans first. Each recovered plan also carries groupName, so Mode 2 can
  // still derive the two folders even if the secondary group write is interrupted.
  await saveData('lessonPlans', lessonPlans, true);
  await saveData('importGroups', importGroups, true);

  return stats;
}

app.post("/api/lesson-plans/recover-legacy-bundle", requireAuth, requireRole(['admin', 'bos', 'superadmin']), async (req: any, res) => {
  try {
    const result = await recoverLegacyLessonPlanBundle(req, req.body || {});
    return res.json({
      success: true,
      message: result.dryRun
        ? `Preview recovery: ${result.recoveredPlans} modul siap dipulihkan ke ${result.targetSubjectName} dalam ${result.recoveredGroups} kelompok.`
        : `Recovery selesai: ${result.recoveredPlans} modul tersedia di ${result.targetSubjectName} dalam ${result.recoveredGroups} kelompok.`,
      result
    });
  } catch (err: any) {
    console.error('[LessonPlan Legacy Recovery] Failed:', err?.message || err);
    return res.status(500).json({
      success: false,
      message: safeServerError(err, 'Recovery modul ajar legacy gagal.')
    });
  }
});


// Google Drive storage for online learning PDFs.
// Preferred online configuration: provide the Service Account key as
// GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON_BASE64 (or GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON)
// and share GOOGLE_DRIVE_FOLDER_ID with that Service Account. If no explicit key
// is configured, Cloud Run falls back to its attached runtime Service Account.
function getConfiguredGoogleServiceAccount(): { clientEmail: string; privateKey: string } | null {
  const encoded = String(process.env.GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON_BASE64 || '').trim();
  const raw = encoded
    ? Buffer.from(encoded, 'base64').toString('utf8')
    : String(process.env.GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON || '').trim();
  if (!raw) return null;

  let parsed: any;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error('GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON tidak valid.');
  }

  const clientEmail = String(parsed?.client_email || '').trim();
  const privateKey = String(parsed?.private_key || '').replace(/\\n/g, '\n').trim();
  if (!clientEmail || !privateKey.includes('BEGIN PRIVATE KEY')) {
    throw new Error('Credential Google Drive tidak memiliki client_email/private_key yang valid.');
  }
  return { clientEmail, privateKey };
}

function base64UrlEncode(value: string | Buffer): string {
  return Buffer.from(value).toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

async function getGoogleDriveServiceAccountAccessToken(): Promise<string> {
  const credentials = getConfiguredGoogleServiceAccount();
  if (!credentials) throw new Error('Credential Service Account Google Drive belum dikonfigurasi.');

  const now = Math.floor(Date.now() / 1000);
  const header = base64UrlEncode(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claim = base64UrlEncode(JSON.stringify({
    iss: credentials.clientEmail,
    scope: 'https://www.googleapis.com/auth/drive',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600
  }));
  const unsignedToken = `${header}.${claim}`;
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(unsignedToken);
  signer.end();
  const signature = base64UrlEncode(signer.sign(credentials.privateKey));
  const assertion = `${unsignedToken}.${signature}`;

  const tokenResponse = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
      assertion
    }).toString()
  });
  if (!tokenResponse.ok) {
    const detail = (await tokenResponse.text()).slice(0, 500);
    throw new Error(`Google OAuth token gagal (${tokenResponse.status}): ${detail}`);
  }
  const payload: any = await tokenResponse.json();
  const token = String(payload?.access_token || '');
  if (!token) throw new Error('Google OAuth tidak mengembalikan access token.');
  return token;
}

function canonicalGoogleDriveTenantId(value: any): string {
  const raw = String(value || 'default').trim() || 'default';
  const matched = (madrasahs || []).find((item: any) =>
    String(item?.id || '') === raw || String(item?.slug || '') === raw
  );
  return String(matched?.id || raw).trim().slice(0, 200) || 'default';
}

function googleDriveOAuthStoreKey(madrasahId: any): string {
  const tenantId = canonicalGoogleDriveTenantId(madrasahId);
  const digest = crypto.createHash('sha256').update(tenantId).digest('hex').slice(0, 24);
  return 'google_drive_oauth:' + digest;
}

async function getStoredGoogleDriveOAuthConnection(madrasahId: any = 'default'): Promise<any | null> {
  if (!pool) {
    try { await dbInitPromise; } catch (_) {}
  }
  if (!pool) return null;

  const tenantId = canonicalGoogleDriveTenantId(madrasahId);
  const scopedKey = googleDriveOAuthStoreKey(tenantId);
  try {
    const scoped = await pool.query("SELECT value FROM app_store WHERE key = $1 LIMIT 1", [scopedKey]);
    const scopedValue = scoped.rows?.[0]?.value;
    if (scopedValue && typeof scopedValue === 'object') return scopedValue;

    const legacy = await pool.query("SELECT value FROM app_store WHERE key = $1 LIMIT 1", ['google_drive_oauth']);
    const legacyValue = legacy.rows?.[0]?.value;
    if (legacyValue && typeof legacyValue === 'object') {
      const legacyTenantId = canonicalGoogleDriveTenantId(legacyValue?.madrasahId || 'default');
      if (legacyTenantId === tenantId) {
        const migratedValue = {
          ...legacyValue,
          madrasahId: tenantId,
          migratedToTenantScopeAt: new Date().toISOString()
        };
        await pool.query(
          `INSERT INTO app_store (key, value)
           VALUES ($1, $2::jsonb)
           ON CONFLICT (key) DO NOTHING`,
          [scopedKey, JSON.stringify(migratedValue)]
        );
        return migratedValue;
      }
    }
    return null;
  } catch (error: any) {
    console.warn('[Google Drive OAuth] Gagal membaca koneksi tersimpan:', error?.message || error);
    return null;
  }
}

async function saveGoogleDriveOAuthConnection(madrasahId: any, patch: any): Promise<void> {
  if (!pool) {
    try { await dbInitPromise; } catch (_) {}
  }
  if (!pool) throw new Error('Database belum siap. Koneksi Google Drive tidak dapat disimpan.');

  const tenantId = canonicalGoogleDriveTenantId(madrasahId);
  const scopedKey = googleDriveOAuthStoreKey(tenantId);
  const current = (await getStoredGoogleDriveOAuthConnection(tenantId)) || {};
  const value = { ...current, ...patch, madrasahId: tenantId };

  await pool.query(
    `INSERT INTO app_store (key, value)
     VALUES ($1, $2::jsonb)
     ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value`,
    [scopedKey, JSON.stringify(value)]
  );
}

async function getStoredGoogleDriveOAuthRefreshToken(madrasahId: any = 'default'): Promise<string | null> {
  try {
    const value = await getStoredGoogleDriveOAuthConnection(madrasahId);
    const encrypted = typeof value === 'string' ? value : value?.refreshToken;
    if (!encrypted) return null;
    return decryptGoogleDriveOAuthToken(String(encrypted));
  } catch (error: any) {
    console.warn('[Google Drive OAuth] Gagal membaca kredensial tersimpan:', error?.message || error);
    return null;
  }
}

async function exchangeGoogleDriveOAuthRefreshToken(refreshToken: string): Promise<string> {
  const clientId = String(process.env.GOOGLE_DRIVE_OAUTH_CLIENT_ID || '').trim();
  const clientSecret = String(process.env.GOOGLE_DRIVE_OAUTH_CLIENT_SECRET || '').trim();
  if (!clientId || !clientSecret) {
    throw new Error('Google Drive OAuth belum lengkap: CLIENT_ID dan CLIENT_SECRET wajib diisi.');
  }
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
      grant_type: 'refresh_token'
    }).toString()
  });
  const payload: any = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error('Google OAuth refresh gagal (' + response.status + '): ' + String(payload.error_description || payload.error || 'unknown_error'));
  }
  const token = String(payload?.access_token || '').trim();
  if (!token) throw new Error('Google OAuth refresh tidak mengembalikan access token.');
  return token;
}

function googleDriveConnectionError(message: string): any {
  const error: any = new Error(message);
  error.code = 'GOOGLE_DRIVE_CONNECTION_REQUIRED';
  return error;
}

function googleDriveOAuthServerConfigured(req: any): boolean {
  return Boolean(
    String(process.env.GOOGLE_DRIVE_OAUTH_CLIENT_ID || '').trim() &&
    String(process.env.GOOGLE_DRIVE_OAUTH_CLIENT_SECRET || '').trim() &&
    getGoogleDriveOAuthRedirectUri(req)
  );
}

async function getGoogleDriveAccessToken(madrasahId: any = 'default'): Promise<string> {
  if (!isTrustedCloudRunRuntime) {
    throw new Error('Google Drive PDF storage hanya tersedia pada runtime Cloud Run.');
  }

  // Preferred Cloud Run path: a user-authorized OAuth refresh token persisted in PostgreSQL.
  const tenantId = canonicalGoogleDriveTenantId(madrasahId);
  const storedRefreshToken = await getStoredGoogleDriveOAuthRefreshToken(tenantId);
  if (storedRefreshToken) {
    try {
      return await exchangeGoogleDriveOAuthRefreshToken(storedRefreshToken);
    } catch (error: any) {
      const detail = String(error?.message || error || '');
      if (/invalid_grant|revoked|expired|refresh/i.test(detail)) {
        throw googleDriveConnectionError('Koneksi Google Drive sudah tidak valid. Hubungkan Google Drive kembali.');
      }
      throw error;
    }
  }

  // Explicit service-account deployments remain supported.
  if (getConfiguredGoogleServiceAccount()) {
    return getGoogleDriveServiceAccountAccessToken();
  }

  // Do not silently use the Cloud Run runtime service account for Drive. That identity
  // usually has no Drive folder/ownership and previously surfaced only as a generic 500.
  if (String(process.env.GOOGLE_DRIVE_USE_RUNTIME_SERVICE_ACCOUNT || '').trim().toLowerCase() === 'true') {
    const tokenResponse = await fetch(
      'http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/token',
      { headers: { 'Metadata-Flavor': 'Google' } }
    );
    if (!tokenResponse.ok) {
      throw googleDriveConnectionError('Service Account runtime Cloud Run belum dapat mengakses Google Drive.');
    }
    const payload: any = await tokenResponse.json();
    const token = String(payload?.access_token || '');
    if (!token) throw googleDriveConnectionError('Access token Google Drive tidak tersedia.');
    return token;
  }

  throw googleDriveConnectionError('Google Drive belum terhubung. Hubungkan akun Google Drive terlebih dahulu.');
}

async function getGoogleDriveFolderId(accessToken: string, madrasahId: any = 'default'): Promise<string> {
  const tenantId = canonicalGoogleDriveTenantId(madrasahId);
  const stored = await getStoredGoogleDriveOAuthConnection(tenantId);
  const storedFolderId = String(stored?.folderId || '').trim();
  if (/^[A-Za-z0-9_-]{10,200}$/.test(storedFolderId)) return storedFolderId;

  const query = encodeURIComponent("name = 'Madrasah Bisa' and mimeType = 'application/vnd.google-apps.folder' and trashed = false");
  const listResponse = await fetch(
    'https://www.googleapis.com/drive/v3/files?q=' + query + '&spaces=drive&fields=files(id,name,trashed)&pageSize=20',
    { headers: { Authorization: 'Bearer ' + accessToken } }
  );
  if (!listResponse.ok) {
    const detail = (await listResponse.text()).slice(0, 800);
    throw new Error('Google Drive gagal membaca folder penyimpanan (' + listResponse.status + '): ' + detail);
  }
  const listed: any = await listResponse.json();
  const existing = Array.isArray(listed?.files) ? listed.files.find((item: any) => /^[A-Za-z0-9_-]{10,200}$/.test(String(item?.id || ''))) : null;
  if (existing?.id) {
    await saveGoogleDriveOAuthConnection(tenantId, { folderId: String(existing.id), folderName: String(existing.name || 'Madrasah Bisa') });
    return String(existing.id);
  }

  const createResponse = await fetch('https://www.googleapis.com/drive/v3/files?fields=id,name', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + accessToken, 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: 'Madrasah Bisa', mimeType: 'application/vnd.google-apps.folder' })
  });
  const created: any = await createResponse.json().catch(() => ({}));
  if (!createResponse.ok || !created?.id) {
    throw new Error('Gagal membuat folder Madrasah Bisa di Google Drive (' + createResponse.status + '): ' + String(created?.error?.message || 'unknown_error'));
  }
  await saveGoogleDriveOAuthConnection(tenantId, { folderId: String(created.id), folderName: 'Madrasah Bisa' });
  return String(created.id);
}

async function uploadLearningPdfToGoogleDrive(buffer: Buffer, displayName: string, req: any): Promise<{ fileId: string; name: string }> {
  const tenantId = canonicalGoogleDriveTenantId(getRequestMadrasahId(req) || 'default');
  const accessToken = await getGoogleDriveAccessToken(tenantId);
  const folderId = await getGoogleDriveFolderId(accessToken, tenantId);
  const tenantHash = crypto.createHash('sha256')
    .update(tenantId)
    .digest('hex')
    .slice(0, 12);
  const suffix = crypto.randomBytes(6).toString('hex');
  const baseName = sanitizeLearningAssetName(displayName, 'Materi.pdf').replace(/\.pdf$/i, '');
  const driveName = sanitizeLearningAssetName(`${baseName} - ${suffix}.pdf`, 'Materi.pdf');
  const metadata = {
    name: driveName,
    mimeType: 'application/pdf',
    parents: [folderId],
    appProperties: {
      managedBy: 'madrasah-bisa-learning-pdf',
      tenantHash
    }
  };
  const boundary = 'madrasah_bisa_' + crypto.randomBytes(12).toString('hex');
  const prefix = Buffer.from(
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n` +
    `--${boundary}\r\nContent-Type: application/pdf\r\n\r\n`,
    'utf8'
  );
  const suffixBuffer = Buffer.from(`\r\n--${boundary}--\r\n`, 'utf8');
  const body = Buffer.concat([prefix, buffer, suffixBuffer]);
  const response = await fetch(
    'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,name,mimeType,parents,appProperties',
    {
      method: 'POST',
      headers: {
        Authorization: 'Bearer ' + accessToken,
        'Content-Type': 'multipart/related; boundary=' + boundary,
        'Content-Length': String(body.length)
      },
      body
    }
  );
  const payload: any = await response.json().catch(() => ({}));
  const fileId = String(payload?.id || '').trim();
  if (!response.ok || !/^[A-Za-z0-9_-]{10,200}$/.test(fileId)) {
    throw new Error('Google Drive gagal menyimpan PDF (' + response.status + '): ' + String(payload?.error?.message || 'unknown_error'));
  }
  return { fileId, name: String(payload?.name || driveName) };
}

async function deleteManagedLearningPdfFromGoogleDrive(fileIdValue: any, req: any): Promise<'deleted' | 'missing' | 'forbidden' | 'failed'> {
  const fileId = String(fileIdValue || '').trim();
  if (!/^[A-Za-z0-9_-]{10,200}$/.test(fileId)) return 'failed';
  try {
    const tenantId = canonicalGoogleDriveTenantId(getRequestMadrasahId(req) || 'default');
    const accessToken = await getGoogleDriveAccessToken(tenantId);
    const metadataResponse = await fetch(
      'https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(fileId) + '?supportsAllDrives=true&fields=id,mimeType,trashed,appProperties',
      { headers: { Authorization: 'Bearer ' + accessToken } }
    );
    if (metadataResponse.status === 404) return 'missing';
    const metadata: any = await metadataResponse.json().catch(() => ({}));
    if (!metadataResponse.ok) return 'failed';

    const tenantHash = crypto.createHash('sha256')
      .update(tenantId)
      .digest('hex')
      .slice(0, 12);
    const props = metadata?.appProperties || {};
    if (
      String(metadata?.mimeType || '') !== 'application/pdf' ||
      String(props?.managedBy || '') !== 'madrasah-bisa-learning-pdf' ||
      String(props?.tenantHash || '') !== tenantHash
    ) {
      return 'forbidden';
    }

    const response = await fetch(
      'https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(fileId) + '?supportsAllDrives=true',
      {
        method: 'DELETE',
        headers: { Authorization: 'Bearer ' + accessToken }
      }
    );
    if (response.status === 404) return 'missing';
    return response.ok ? 'deleted' : 'failed';
  } catch (err: any) {
    console.warn('[Google Drive Learning PDF] Delete failed:', err?.message || err);
    return 'failed';
  }
}

async function streamLearningPdfFromGoogleDrive(fileId: string, req: any, res: any): Promise<void> {
  const safeFileId = String(fileId || '').trim();
  if (!/^[A-Za-z0-9_-]{10,200}$/.test(safeFileId)) {
    res.status(400).end();
    return;
  }

  const tenantId = canonicalGoogleDriveTenantId(getRequestMadrasahId(req) || 'default');
  const accessToken = await getGoogleDriveAccessToken(tenantId);
  const metadataResponse = await fetch(
    'https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(safeFileId) +
      '?supportsAllDrives=true&fields=id,mimeType,trashed,appProperties',
    {
      headers: { Authorization: 'Bearer ' + accessToken },
      redirect: 'error'
    }
  );

  if (metadataResponse.status === 404) {
    res.status(404).end();
    return;
  }
  if (!metadataResponse.ok) {
    console.warn('[Google Drive PDF] Metadata gagal:', metadataResponse.status);
    res.status(metadataResponse.status === 403 ? 403 : 502).end();
    return;
  }

  const metadata: any = await metadataResponse.json().catch(() => ({}));
  const expectedTenantHash = crypto.createHash('sha256').update(tenantId).digest('hex').slice(0, 12);
  const props = metadata?.appProperties || {};
  const ownedByTenant =
    String(metadata?.mimeType || '') === 'application/pdf' &&
    metadata?.trashed !== true &&
    String(props?.managedBy || '') === 'madrasah-bisa-learning-pdf' &&
    String(props?.tenantHash || '') === expectedTenantHash;

  if (!ownedByTenant) {
    console.warn('[Google Drive PDF] Tenant ownership ditolak untuk file:', safeFileId);
    res.status(403).end();
    return;
  }

  const response = await fetch(
    'https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(safeFileId) + '?alt=media&supportsAllDrives=true',
    {
      headers: { Authorization: 'Bearer ' + accessToken },
      redirect: 'error'
    }
  );

  if (!response.ok) {
    console.warn('[Google Drive PDF] Download gagal:', response.status);
    res.status(response.status === 404 ? 404 : 502).end();
    return;
  }

  const declaredLength = Number(response.headers.get('content-length') || 0);
  if (declaredLength > MAX_LEARNING_PDF_BYTES) {
    res.status(413).end();
    return;
  }

  const buffer = Buffer.from(await response.arrayBuffer());
  if (!buffer.length || buffer.length > MAX_LEARNING_PDF_BYTES) {
    res.status(413).end();
    return;
  }
  if (buffer.length < 5 || buffer.subarray(0, 5).toString('ascii') !== '%PDF-') {
    res.status(415).end();
    return;
  }

  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Length', String(buffer.length));
  res.setHeader('Content-Disposition', 'inline');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'private, no-store');
  res.send(buffer);
}

app.post(
  "/api/learning/assets/pdf",
  requireAuth,
  requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']),
  parseLearningPdfUploadBody,
  async (req: any, res) => {
    try {
      const contentType = String(req.headers['content-type'] || '').toLowerCase();
      if (!contentType.startsWith('application/pdf') && !contentType.startsWith('application/octet-stream')) {
        return res.status(415).json({ success: false, message: 'Content-Type upload PDF tidak valid.' });
      }

      const parsed = parseSafePdfBuffer(req.body);
      if (!parsed) {
        return res.status(415).json({
          success: false,
          message: 'File bukan PDF yang valid atau ukurannya melebihi 15 MB.'
        });
      }

      const originalName = String(req.query?.name || 'Materi.pdf');
      const tenantHash = crypto.createHash('sha256')
        .update(String(getRequestMadrasahId(req) || 'default'))
        .digest('hex')
        .slice(0, 12);
      const assetId = `la_${tenantHash}_${crypto.randomBytes(18).toString('hex')}.pdf`;
      const displayName = sanitizeLearningAssetName(originalName, 'Materi.pdf');

      if (isOfflineMode) {
        if (!fs.existsSync(learningAssetsDir)) fs.mkdirSync(learningAssetsDir, { recursive: true });
        const targetPath = path.resolve(learningAssetsDir, assetId);
        const root = path.resolve(learningAssetsDir) + path.sep;
        if (!targetPath.startsWith(root)) {
          return res.status(400).json({ success: false, message: 'Nama aset tidak valid.' });
        }
        fs.writeFileSync(targetPath, parsed.buffer);
        return res.json({
          success: true,
          asset: {
            type: 'pdf',
            url: `/api/learning-assets/${assetId}`,
            driveFileId: '',
            name: displayName,
            mime: parsed.mime,
            size: parsed.buffer.length
          }
        });
      }

      const uploaded = await uploadLearningPdfToGoogleDrive(parsed.buffer, displayName, req);
      return res.json({
        success: true,
        asset: {
          type: 'pdf',
          url: '',
          driveFileId: uploaded.fileId,
          name: displayName,
          mime: parsed.mime,
          size: parsed.buffer.length,
          storage: 'google-drive'
        }
      });
    } catch (err: any) {
      const detail = String(err?.message || '');
      console.warn('[Learning PDF Upload] Failed:', err?.code || err?.http_code || err?.name || '', detail || err);

      if (err?.code === 'GOOGLE_DRIVE_CONNECTION_REQUIRED') {
        return res.status(428).json({
          success: false,
          code: 'GOOGLE_DRIVE_CONNECTION_REQUIRED',
          requiresGoogleDriveConnection: true,
          message: 'Google Drive belum terhubung untuk madrasah ini. Hubungkan melalui menu Pengaturan → Google Drive Materi Pembelajaran.'
        });
      }

      const oauthConfigIssue = /Google Drive OAuth belum lengkap|CLIENT_ID|CLIENT_SECRET|REDIRECT_URI/i.test(detail);
      if (oauthConfigIssue) {
        return res.status(503).json({
          success: false,
          code: 'GOOGLE_DRIVE_SERVER_CONFIG_REQUIRED',
          message: 'Konfigurasi Google Drive OAuth di server belum lengkap.'
        });
      }

      return res.status(500).json({
        success: false,
        message: safeServerError(err, 'Upload PDF materi gagal.')
      });
    }
  }
);

app.post("/api/learning/assets", requireAuth, requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']), async (req: any, res) => {
  try {
    const rawData = String(req.body?.data || '');
    const originalName = String(req.body?.name || '');
    const parsedImage = parseSafeRasterDataUrl(rawData);
    const parsedPdf = parsedImage ? null : parseSafePdfDataUrl(rawData);
    const parsedVideo = parsedImage || parsedPdf ? null : parseSafeVideoDataUrl(rawData);
    const parsed = parsedImage || parsedPdf || parsedVideo;
    if (!parsed) {
      return res.status(400).json({
        success: false,
        message: 'File tidak didukung. Gunakan JPG/PNG/WebP maksimal 10 MB, PDF maksimal 15 MB, atau MP4/WebM/OGG maksimal 18 MB.'
      });
    }

    const isPdf = parsed.mime === 'application/pdf';
    const isVideo = parsed.mime.startsWith('video/');
    const extension = isPdf ? '.pdf' : isVideo ? (parsed as any).extension : (parsed.mime === 'image/png' ? '.png' : parsed.mime === 'image/webp' ? '.webp' : '.jpg');
    const tenantHash = crypto.createHash('sha256').update(String(getRequestMadrasahId(req) || 'default')).digest('hex').slice(0, 12);
    const assetId = `la_${tenantHash}_${crypto.randomBytes(18).toString('hex')}${extension}`;
    const displayName = sanitizeLearningAssetName(originalName, isPdf ? 'Materi.pdf' : isVideo ? `Video${extension}` : `Gambar${extension}`);

    if (isOfflineMode) {
      if (!fs.existsSync(learningAssetsDir)) fs.mkdirSync(learningAssetsDir, { recursive: true });
      const targetPath = path.join(learningAssetsDir, assetId);
      if (!targetPath.startsWith(path.resolve(learningAssetsDir) + path.sep) && path.resolve(targetPath) !== path.resolve(learningAssetsDir, assetId)) {
        return res.status(400).json({ success: false, message: 'Nama aset tidak valid.' });
      }
      fs.writeFileSync(targetPath, parsed.buffer);
      return res.json({
        success: true,
        asset: { type: isPdf ? 'pdf' : isVideo ? 'video' : 'image', url: `/api/learning-assets/${assetId}`, driveFileId: '', name: displayName, mime: parsed.mime, size: parsed.buffer.length }
      });
    }

    // Online: PDFs are stored in Google Drive. Cloudinary remains only for images/videos.
    if (isPdf) {
      const uploaded = await uploadLearningPdfToGoogleDrive(parsed.buffer, displayName, req);
      return res.json({
        success: true,
        asset: {
          type: 'pdf',
          url: '',
          driveFileId: uploaded.fileId,
          name: displayName,
          mime: parsed.mime,
          size: parsed.buffer.length,
          storage: 'google-drive'
        }
      });
    }

    const cloudinaryConfig = cloudinary.config();
    const cloudName = String(cloudinaryConfig?.cloud_name || '').trim();
    const cloudApiKey = String(cloudinaryConfig?.api_key || '').trim();
    const cloudApiSecret = String(cloudinaryConfig?.api_secret || '').trim();
    if (!cloudName || !cloudApiKey || !cloudApiSecret) {
      throw new Error('Cloudinary belum terkonfigurasi. Isi CLOUDINARY_URL atau CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, dan CLOUDINARY_API_SECRET pada environment deployment.');
    }

    const publicId = assetId.replace(/\.[A-Za-z0-9]+$/, '');
    const uploadOptions: any = {
      folder: `madrasah_learning_assets/${tenantHash}`,
      resource_type: isVideo ? 'video' : 'image',
      public_id: publicId,
      overwrite: false
    };
    const uploaded = await new Promise<any>((resolve, reject) => {
      // Upload the already-validated binary buffer instead of the Base64 data URI.
      // This avoids data-URI parsing differences between Cloudinary SDK versions.
      const uploadStream = cloudinary.uploader.upload_stream(uploadOptions, (error, result) => {
        if (error) reject(error);
        else resolve(result);
      });
      uploadStream.end(parsed.buffer);
    });
    const url = String(uploaded?.secure_url || uploaded?.url || '');
    if (!url || !isTrustedLearningAssetUrl(url)) throw new Error('Cloudinary tidak mengembalikan URL aset materi yang valid.');

    return res.json({
      success: true,
      asset: { type: isVideo ? 'video' : 'image', url, driveFileId: '', name: displayName, mime: parsed.mime, size: parsed.buffer.length }
    });
  } catch (err: any) {
    const detail = String(err?.message || '');
    console.warn('[Learning Asset Upload] Failed:', err?.http_code || err?.name || '', detail || err);
    // Keep the generic production message for unexpected failures.
    const actionable =
      /Cloudinary belum terkonfigurasi/i.test(detail)
        ? detail.slice(0, 700)
        : safeServerError(err, 'Upload aset materi gagal.');
    return res.status(500).json({ success: false, message: actionable || 'Upload aset materi gagal.' });
  }
});

app.delete("/api/learning/assets", requireAuth, requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']), async (req: any, res: any) => {
  try {
    const url = String(req.body?.url || '').trim();
    const driveFileId = String(req.body?.driveFileId || '').trim();

    if (!isOfflineMode && driveFileId) {
      const outcome = await deleteManagedLearningPdfFromGoogleDrive(driveFileId, req);
      if (outcome === 'forbidden') return res.status(403).json({ success: false, message: 'PDF Google Drive bukan milik madrasah ini.' });
      if (outcome === 'failed') return res.status(502).json({ success: false, message: 'PDF Google Drive belum dapat dihapus.' });
      return res.json({ success: true, deleted: true, storage: 'google-drive' });
    }

    if (!url) return res.status(400).json({ success: false, message: 'Referensi aset wajib diisi.' });

    if (isOfflineMode) {
      const match = url.match(/^\/api\/learning-assets\/([A-Za-z0-9._-]{20,180})$/);
      if (!match) return res.status(400).json({ success: false, message: 'Aset lokal tidak valid.' });
      const root = path.resolve(learningAssetsDir) + path.sep;
      const filePath = path.resolve(learningAssetsDir, match[1]);
      if (!filePath.startsWith(root)) return res.status(400).json({ success: false, message: 'Aset lokal tidak valid.' });
      try { if (fs.existsSync(filePath)) fs.unlinkSync(filePath); } catch {}
      return res.json({ success: true, deleted: true });
    }

    const tenantHash = crypto.createHash('sha256').update(String(getRequestMadrasahId(req) || 'default')).digest('hex').slice(0, 12);
    let parsedUrl: URL;
    try { parsedUrl = new URL(url); } catch { return res.status(400).json({ success: false, message: 'URL aset tidak valid.' }); }
    if (parsedUrl.protocol !== 'https:' || parsedUrl.hostname !== 'res.cloudinary.com' || !parsedUrl.pathname.includes('/madrasah_learning_assets/' + tenantHash + '/')) {
      return res.status(403).json({ success: false, message: 'Aset bukan milik madrasah ini.' });
    }
    const refs = extractLearningCloudinaryRefs(url);
    const asset = refs.values().next().value;
    if (!asset) return res.status(400).json({ success: false, message: 'Aset Cloudinary tidak dikenali.' });
    const outcome = await destroyCloudinaryLearningAsset(asset);
    if (outcome === 'failed') return res.status(502).json({ success: false, message: 'Aset belum dapat dihapus dari Cloudinary.' });
    return res.json({ success: true, deleted: true });
  } catch (err: any) {
    console.warn('[Learning Asset Rollback] Failed:', err?.message || err);
    return res.status(500).json({ success: false, message: safeServerError(err, 'Rollback aset Materi gagal.') });
  }
});

app.get("/api/learning-assets/drive-pdf", async (req: any, res: any) => {
  try {
    // Prefer the normal application auth headers. The query-token fallback exists
    // only for older browsers/proxies that strip Authorization headers from GETs.
    let authUser = req.user || getLearningAuthUser(req);
    if (!authUser) {
      const queryToken = String(req.query?.auth || '').trim();
      if (queryToken) authUser = verifyLearningAuthToken(queryToken);
    }
    if (authUser) req.user = authUser;
    if (!authUser) {
      return res.status(401).json({ success: false, message: "Akses ditolak: Silakan login terlebih dahulu." });
    }
    await streamLearningPdfFromGoogleDrive(String(req.query?.id || '').trim(), req, res);
  } catch (err: any) {
    console.warn('[Google Drive PDF] Failed:', err?.message || err);
    if (!res.headersSent) res.status(500).end();
  }
});

app.get("/api/learning-assets/inline-pdf", async (req: any, res: any) => {
  try {
    const authUser = req.user || getLearningAuthUser(req);
    if (!authUser) return res.status(401).json({ success: false, message: 'Akses ditolak: Silakan login terlebih dahulu.' });

    const rawUrl = String(req.query?.url || '').trim();
    const url = new URL(rawUrl);
    const routeMatch = url.pathname.match(/^\/(raw|image)\/upload\/v\d+\/madrasah_learning_assets\//i);
    if (url.protocol !== 'https:' || url.hostname !== 'res.cloudinary.com' || !routeMatch || !/\.pdf(?:$|[?#])/i.test(url.pathname)) {
      return res.status(400).end();
    }
    if (!process.env.CLOUDINARY_CLOUD_NAME || !process.env.CLOUDINARY_API_KEY || !process.env.CLOUDINARY_API_SECRET) return res.status(503).end();

    const resourceType = String(routeMatch[1]).toLowerCase() === 'raw' ? 'raw' : 'image';
    const pathParts = url.pathname.split('/').filter(Boolean);
    const versionIndex = pathParts.findIndex((part) => /^v\d+$/.test(part));
    if (versionIndex < 0 || pathParts[versionIndex + 1] !== 'madrasah_learning_assets') return res.status(400).end();
    const rawPublicId = pathParts.slice(versionIndex + 1).join('/');
    const publicId = resourceType === 'raw' ? rawPublicId : rawPublicId.replace(/\.pdf$/i, '');
    if (!publicId || publicId.length > 500 || !/^[A-Za-z0-9_./-]+$/.test(publicId)) return res.status(400).end();

    // Enforce tenant ownership before proxying any Cloudinary document.
    const tenantHash = crypto.createHash('sha256')
      .update(String(getRequestMadrasahId(req) || 'default'))
      .digest('hex')
      .slice(0, 12);
    const expectedPrefix = `madrasah_learning_assets/${tenantHash}/`;
    if (!publicId.startsWith(expectedPrefix)) return res.status(403).end();

    // Never fetch the public raw/upload URL directly. Some Cloudinary environments
    // intentionally return 401 for PDF/raw delivery. Generate a short-lived signed
    // API download URL instead, then stream the bytes through our authenticated app.
    const downloadUrl = cloudinary.utils.private_download_url(publicId, 'pdf', {
      resource_type: resourceType,
      type: 'upload',
      expires_at: Math.floor(Date.now() / 1000) + 300
    });
    const response = await fetch(downloadUrl, { redirect: 'error' });
    if (!response.ok) {
      console.warn(`[Learning PDF] Cloudinary signed download gagal: ${response.status}`);
      return res.status(response.status).end();
    }

    const buffer = Buffer.from(await response.arrayBuffer());
    if (!buffer.length || buffer.length > MAX_LEARNING_PDF_BYTES) return res.status(413).end();
    if (buffer.length < 5 || buffer.subarray(0, 5).toString('ascii') !== '%PDF-') return res.status(415).end();
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Length', String(buffer.length));
    res.setHeader('Content-Disposition', 'inline');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, no-store');
    return res.send(buffer);
  } catch (err: any) {
    console.warn('[Learning PDF inline] Failed:', err?.message || err);
    if (!res.headersSent) res.status(400).end();
  }
});

app.get("/api/learning-assets/serve", async (req: any, res: any) => {
  const rawUrl = String(req.query?.url || '').trim();
  try {
    const url = new URL(rawUrl);
    if (
      url.protocol !== 'https:' ||
      url.hostname !== 'res.cloudinary.com' ||
      !url.pathname.includes('/madrasah_learning_assets/') ||
      !/^\/image\/upload\/v\d+\/madrasah_learning_assets\//i.test(url.pathname)
    ) {
      return res.status(400).end();
    }

    if (!process.env.CLOUDINARY_CLOUD_NAME ||
        !process.env.CLOUDINARY_API_KEY ||
        !process.env.CLOUDINARY_API_SECRET) {
      return res.status(503).end();
    }

    const pathParts = url.pathname.split('/').filter(Boolean);
    const versionIndex = pathParts.findIndex((part) => /^v\d+$/.test(part));
    if (versionIndex < 0 || pathParts[versionIndex + 1] !== 'madrasah_learning_assets') {
      return res.status(400).end();
    }

    const assetPart = pathParts.slice(versionIndex + 2).join('/');
    const extensionMatch = assetPart.match(/\.([A-Za-z0-9]+)$/);
    const format = extensionMatch ? extensionMatch[1].toLowerCase() : '';
    const publicId = assetPart.replace(/\.[A-Za-z0-9]+$/, '');
    if (!publicId || publicId.length > 500) return res.status(400).end();

    const resourceType = format === 'mp4' || format === 'webm' || format === 'ogv' || format === 'ogg'
      ? 'video'
      : 'image';

    const signedDownloadUrl = cloudinary.utils.private_download_url(
      publicId,
      format || (resourceType === 'video' ? 'mp4' : 'jpg'),
      {
        resource_type: resourceType,
        type: 'upload',
        expires_at: Math.floor(Date.now() / 1000) + 300
      }
    );

    const response = await fetch(signedDownloadUrl, { redirect: 'error' });
    if (!response.ok) {
      console.warn(`[Learning Asset] Cloudinary signed download gagal: ${response.status}`);
      return res.status(response.status).end();
    }

    const contentType = String(response.headers.get('content-type') || '').toLowerCase();
    const buffer = Buffer.from(await response.arrayBuffer());
    if (!buffer.length || buffer.length > MAX_LEARNING_VIDEO_BYTES) return res.status(413).end();

    const isPdf = format === 'pdf' || contentType.includes('application/pdf');
    const isVideo = resourceType === 'video' || contentType.startsWith('video/');
    const safeContentType = isPdf ? 'application/pdf'
      : isVideo ? (contentType.startsWith('video/') ? contentType : `video/${format || 'mp4'}`)
      : (contentType.startsWith('image/') ? contentType : `image/${format || 'jpeg'}`);

    res.setHeader('Content-Type', safeContentType);
    res.setHeader('Content-Disposition', isPdf ? 'inline' : 'inline');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, max-age=300');
    res.setHeader('Content-Length', String(buffer.length));
    return res.send(buffer);
  } catch (err: any) {
    console.error('[Learning Asset] Gagal mengambil asset Cloudinary:', err?.message || err);
    return res.status(400).end();
  }
});

app.get("/api/learning-assets/:assetId", (req, res) => {
  if (!isOfflineMode) return res.status(404).end();
  const assetId = String(req.params.assetId || '');
  if (!assetId || assetId.length > 180 || !/^[A-Za-z0-9._-]+$/.test(assetId) || path.basename(assetId) !== assetId) {
    return res.status(400).end();
  }
  const filePath = path.join(learningAssetsDir, assetId);
  const root = path.resolve(learningAssetsDir) + path.sep;
  const resolved = path.resolve(filePath);
  if (!resolved.startsWith(root) || !fs.existsSync(resolved)) return res.status(404).end();

  try {
    const buffer = fs.readFileSync(resolved);
    const rasterMime = sniffSafeRasterMime(buffer);
    const isPdf = buffer.length >= 5 && buffer.subarray(0, 5).toString('ascii') === '%PDF-';
    const ext = path.extname(assetId).toLowerCase();
    const videoMime = ext === '.webm' ? 'video/webm' : ext === '.ogv' || ext === '.ogg' ? 'video/ogg' : ext === '.mp4' ? 'video/mp4' : '';
    const mime = rasterMime || (isPdf ? 'application/pdf' : videoMime);
    if (!mime) return res.status(415).end();
    res.setHeader('Content-Type', mime);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'private, max-age=3600');
    if (mime.startsWith('video/')) {
      res.setHeader('Accept-Ranges', 'bytes');
      const range = String(req.headers.range || '');
      const match = range.match(/^bytes=(\d*)-(\d*)$/);
      if (match) {
        const start = match[1] ? Number(match[1]) : 0;
        const end = match[2] ? Number(match[2]) : buffer.length - 1;
        if (Number.isInteger(start) && Number.isInteger(end) && start >= 0 && start < buffer.length && end >= start) {
          const boundedEnd = Math.min(end, buffer.length - 1);
          res.status(206);
          res.setHeader('Content-Range', `bytes ${start}-${boundedEnd}/${buffer.length}`);
          res.setHeader('Content-Length', String(boundedEnd - start + 1));
          return res.send(buffer.subarray(start, boundedEnd + 1));
        }
        res.status(416).setHeader('Content-Range', `bytes */${buffer.length}`).end();
        return;
      }
      res.setHeader('Content-Length', String(buffer.length));
    }
    if (isPdf) {
      res.setHeader('Content-Disposition', `inline; filename="${sanitizeLearningAssetName(assetId, 'materi.pdf')}"`);
      res.setHeader('Content-Security-Policy', 'sandbox');
    }
    return res.send(buffer);
  } catch (_) {
    return res.status(404).end();
  }
});
app.get("/api/learning/materials", requireAuth, (req: any, res) => {
  const authUser = req.user || getAuthUser(req);
  const role = String(authUser?.role || '').toLowerCase();
  const isStudentRole = ['student', 'siswa', 'class_leader', 'ketua_kelas'].includes(role);

  if (isStudentRole) {
    const own = findStudentForRequest(req, authUser?.id);
    if (own.ambiguous) return res.status(409).json({ success: false, message: 'Identitas siswa ambigu pada tenant ini.' });
    if (!own.student) return res.status(404).json({ success: false, message: 'Identitas siswa tidak ditemukan pada tenant ini.' });
    const ownProgress = learningProgressForRequest(req)
      .filter((item: any) => String(item.studentId || '') === String(authUser.id));
    const progressByMaterial = new Map(ownProgress.map((item: any) => [String(item.materialId || ''), item]));
    const completedIds = new Set(ownProgress
      .filter((item: any) => item.status === 'completed' || Number(item.progressPercent || 0) >= 100)
      .map((item: any) => String(item.materialId || '')));
    const materials = filterLessonPlansForRequest(req)
      .filter((material: any) => studentCanAccessLearningMaterial(own.student, material))
      .map((material: any) => {
        const prereq = Array.isArray(material.prerequisiteMaterialIds) ? material.prerequisiteMaterialIds.map(String) : [];
        const locked = prereq.some((id: string) => !completedIds.has(id));
        const linkedLkpd = material.lkpdId
          ? (lkpdList || []).find((item: any) => String(item.id) === String(material.lkpdId) && isItemForCurrentMadrasah(item, req))
          : null;
        const linkedExam = material.examId
          ? (exams || []).find((item: any) => String(item.id) === String(material.examId) && isItemForCurrentMadrasah(item, req))
          : null;
        return {
          ...sanitizeLearningMaterialForStudent(material),
          progress: progressByMaterial.get(String(material.id || '')) || null,
          locked,
          lockedBy: locked ? prereq.filter((id: string) => !completedIds.has(id)) : [],
          linkedActivities: {
            lkpdReady: Boolean(linkedLkpd && studentCanAccessLkpd(own.student, linkedLkpd)),
            examReady: Boolean(linkedExam && studentCanAccessExam(own.student, linkedExam))
          }
        };
      });
    return res.json({ success: true, materials, progress: ownProgress });
  }

  if (!staffRoles.has(role)) {
    return res.status(403).json({ success: false, message: 'Akses materi hanya untuk warga madrasah.' });
  }

  const materials = learningMaterialsForStaffRequest(req);
  res.json({ success: true, materials, data: materials });
});

app.post("/api/learning/materials", requireAuth, requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']), async (req: any, res) => {
  try {
    const requestedId = req.body?.id;
    const resolved = requestedId ? resolveLearningMaterialForRequest(req, requestedId) : { material: null, index: -1, ambiguous: false };
    if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID materi ambigu lintas tenant.' });
    if (resolved.material && isTeacherRequest(req) && !teacherCanUseLearningMaterialPayload(req, resolved.material)) {
      return res.status(403).json({ success: false, message: 'Guru tidak dapat mengubah materi di luar mata pelajaran yang diampu.' });
    }

    let material = sanitizeLearningMaterialMutation(req, req.body || {}, resolved.material || {});
    const createLkpdDraft = req.body?.createLkpdDraft === true;
    const createExamDraft = req.body?.createExamDraft === true;
    const nextLessonPlans = [...(lessonPlans as any[])];
    const nextLkpds = [...(lkpdList || [])];
    const nextExams = [...(exams || [])];
    const batch: any[] = [];

    if (createLkpdDraft && !material.lkpdId) {
      const draftId = ('LKPD_' + String(material.id || '')).slice(0, 256);
      let draft = nextLkpds.find((item: any) =>
        String(item.id || '') === draftId && isItemForCurrentMadrasah(item, req)
      );
      if (!draft) {
        const targetClasses = classTargetsFromLearningMaterial(material);
        const normalizedTargetClasses = targetClasses.length ? targetClasses : ['ALL'];
        const targetClassId = String(normalizedTargetClasses[0] || 'ALL');
        const classRecord = (classes || []).find((item: any) =>
          String(item.id || '') === targetClassId && isItemForCurrentMadrasah(item, req)
        );
        draft = tagNewRecord({
          id: draftId,
          title: ('LKPD - ' + material.title).slice(0, 240),
          subjectId: material.subjectId || material.subjectName || '',
          subjectName: material.subjectName || material.subjectId || '',
          classId: targetClassId || 'ALL',
          classes: normalizedTargetClasses,
          className: targetClassId === 'ALL' ? 'Semua Kelas' : (normalizedTargetClasses.length > 1 ? 'Beberapa Kelas' : (classRecord?.name || targetClassId)),
          answeringMode: 'below',
          description: ('Draft otomatis dari materi: ' + material.title).slice(0, 1000),
          date: '',
          durationMinutes: 45,
          status: 'inactive',
          allowDownloadPdf: true,
          markers: [],
          submissions: [],
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          sourceLearningMaterialId: material.id
        }, req);
        nextLkpds.unshift(draft);
      }
      material = { ...material, lkpdId: draftId };
    }

    if (createExamDraft && !material.examId) {
      const draftId = ('EX_' + String(material.id || '')).slice(0, 256);
      let draft = nextExams.find((item: any) =>
        String(item.id || '') === draftId && isItemForCurrentMadrasah(item, req)
      );
      if (!draft) {
        const targetClasses = classTargetsFromLearningMaterial(material);
        const normalizedTargetClasses = targetClasses.length ? targetClasses : ['ALL'];
        const targetClassId = String(normalizedTargetClasses[0] || 'ALL');
        draft = tagNewRecord({
          id: draftId,
          title: ('Asesmen - ' + material.title).slice(0, 240),
          eventId: 'EV_HARIAN',
          subject: material.subjectName || material.subjectId || '',
          subjectId: material.subjectId || '',
          bankCode: '',
          questionCount: null,
          qCount: null,
          essayCount: null,
          duration: 60,
          date: '',
          startTime: '07:30',
          endTime: '',
          type: 'pilihan_ganda',
          weightType: 'auto',
          weightPg: 50,
          weightEssay: 50,
          autoBlock: 0,
          classes: normalizedTargetClasses,
          shuffleQ: false,
          shuffleOpt: false,
          showScore: false,
          allowDownloadResult: false,
          status: 'Draft',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          sourceLearningMaterialId: material.id
        }, req);
        nextExams.push(draft);
      }
      material = { ...material, examId: draftId, scheduleId: draftId };
    }

    if (resolved.index >= 0) nextLessonPlans[resolved.index] = { ...nextLessonPlans[resolved.index], ...material };
    else nextLessonPlans.push(material);

    batch.push({ key: 'lessonPlans', value: nextLessonPlans });
    if (createLkpdDraft) batch.push({ key: 'lkpdList', value: nextLkpds });
    if (createExamDraft) batch.push({ key: 'exams', value: nextExams });
    await saveDataBatch(batch);

    lessonPlans = nextLessonPlans;
    if (createLkpdDraft) lkpdList = nextLkpds;
    if (createExamDraft) exams = nextExams;

    res.json({
      success: true,
      material,
      data: material,
      createdDrafts: {
        lkpdId: createLkpdDraft ? material.lkpdId : '',
        examId: createExamDraft ? material.examId : ''
      },
      lessonPlans: learningMaterialsForStaffRequest(req)
    });
  } catch (err: any) {
    const message = safeServerError(err, 'Materi gagal disimpan.');
    const status = /tidak ditemukan|tidak dapat|hanya dapat|wajib|tidak valid/i.test(message) ? 400 : 500;
    res.status(status).json({ success: false, message });
  }
});

app.put("/api/learning/materials/:id/publish", requireAuth, requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']), async (req: any, res) => {
  const resolved = resolveLearningMaterialForRequest(req, req.params.id);
  if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID materi ambigu lintas tenant.' });
  if (!resolved.material || resolved.index < 0) return res.status(404).json({ success: false, message: 'Materi tidak ditemukan pada madrasah ini.' });
  if (isTeacherRequest(req) && !teacherCanUseLearningMaterialPayload(req, resolved.material)) {
    return res.status(403).json({ success: false, message: 'Guru tidak dapat menerbitkan materi di luar mata pelajaran yang diampu.' });
  }
  const status = req.body?.status === 'draft' || req.body?.published === false ? 'draft' : 'published';
  (lessonPlans as any[])[resolved.index] = { ...resolved.material, status, updatedAt: new Date().toISOString() };
  await saveData('lessonPlans', lessonPlans);
  res.json({ success: true, material: (lessonPlans as any[])[resolved.index] });
});


function normalizeLearningCloudinaryId(value: string, resourceType = ''): string {
  const clean = String(value || '').split(/[?#]/)[0];
  return String(resourceType || '').toLowerCase() === 'raw'
    ? clean
    : clean.replace(/\.(?:pdf|jpe?g|png|webp|gif|mp4|webm|ogg|mov)$/i, '');
}
function addLearningCloudinaryRef(out: Map<string, any>, publicIdValue: any, resourceTypeValue: any, urlValue?: any) {
  const rawPublicId = String(publicIdValue || '').trim();
  if (!rawPublicId || !rawPublicId.includes('madrasah_learning_assets/')) return;

  let resourceType = String(resourceTypeValue || '').toLowerCase().trim();
  const url = String(urlValue || '').trim();
  if (!['image', 'video', 'raw'].includes(resourceType)) {
    if (/\/raw\//i.test(url)) resourceType = 'raw';
    else if (/\/video\//i.test(url)) resourceType = 'video';
    else if (/\/image\//i.test(url)) resourceType = 'image';
  }
  if (!['image', 'video', 'raw'].includes(resourceType)) return;

  const publicId = normalizeLearningCloudinaryId(rawPublicId, resourceType);
  if (!publicId) return;
  out.set(resourceType + ':' + publicId, { publicId, resourceType, url });
}

function extractLearningCloudinaryRefs(value: any, out = new Map<string, any>(), depth = 0) {
  if (depth > 12 || value == null) return out;

  if (typeof value === 'string') {
    if (!value.includes('res.cloudinary.com') || !value.includes('/madrasah_learning_assets/')) return out;
    try {
      const url = new URL(value);
      const match = url.pathname.match(/^\/(?:image|video|raw)\/upload\/(?:[^/]+\/)*((?:madrasah_learning_assets)\/.+)$/i);
      if (!match) return out;
      const resourceType = /^\/raw\//i.test(url.pathname)
        ? 'raw'
        : (/^\/video\//i.test(url.pathname) ? 'video' : 'image');
      addLearningCloudinaryRef(out, match[1], resourceType, value);
    } catch (_) {}
    return out;
  }

  if (Array.isArray(value)) {
    for (const item of value) extractLearningCloudinaryRefs(item, out, depth + 1);
    return out;
  }

  if (typeof value === 'object') {
    const publicId = value.publicId ?? value.public_id ?? value.cloudinaryPublicId ?? value.cloudinary_public_id;
    const resourceType = value.resourceType ?? value.resource_type ?? value.cloudinaryResourceType ?? value.cloudinary_resource_type;
    const url = value.url ?? value.secure_url ?? value.secureUrl ?? value.cloudinaryUrl ?? value.cloudinary_url;
    if (publicId) addLearningCloudinaryRef(out, publicId, resourceType, url);

    for (const item of Object.values(value)) extractLearningCloudinaryRefs(item, out, depth + 1);
  }
  return out;
}
async function listActualCloudinaryLearningAssets(req: any): Promise<Map<string, any>> {
  if (!process.env.CLOUDINARY_CLOUD_NAME || !process.env.CLOUDINARY_API_KEY || !process.env.CLOUDINARY_API_SECRET) throw new Error('Cloudinary belum dikonfigurasi.');
  const tenantHash = crypto.createHash('sha256').update(String(getRequestMadrasahId(req) || 'default')).digest('hex').slice(0, 12);
  const prefix = 'madrasah_learning_assets/' + tenantHash;
  const assets = new Map<string, any>();
  for (const resourceType of ['image', 'video', 'raw'] as const) {
    let nextCursor: string | null = null;
    do {
      const response: any = await cloudinary.api.resources({ type: 'upload', resource_type: resourceType, prefix, max_results: 500, next_cursor: nextCursor || undefined });
      for (const item of (Array.isArray(response?.resources) ? response.resources : [])) {
        if (!item?.public_id) continue;
        const publicId = normalizeLearningCloudinaryId(String(item.public_id), resourceType);
        if (publicId) assets.set(resourceType + ':' + publicId, { publicId, resourceType, url: String(item.secure_url || item.url || '') });
      }
      nextCursor = response?.next_cursor || null;
    } while (nextCursor);
  }
  return assets;
}
function collectReferencedLearningCloudinaryAssets(): Map<string, any> {
  const refs = new Map<string, any>();
  for (const source of [lessonPlans || [], lkpdList || [], exams || [], generatedExams || [], eduGames || [], appSettings || {}]) {
    extractLearningCloudinaryRefs(source, refs);
  }
  return refs;
}

async function collectPersistedLearningCloudinaryAssets(): Promise<Map<string, any>> {
  const refs = new Map<string, any>();

  // Scan the actual persistent source of truth as well as hydrated runtime state.
  // This avoids false orphan reports when legacy/partitioned learning data is
  // stored under a different app_store key than the normalized lessonPlans array.
  if (pool) {
    try {
      const result = await pool.query('SELECT key, value FROM app_store');
      const dbData = parseDbRows(result.rows || []);
      for (const [key, value] of Object.entries(dbData)) {
        extractLearningCloudinaryRefs({ key, value }, refs);
      }
    } catch (err: any) {
      console.warn('[Cloudinary Learning Audit] Persistent app_store scan failed:', err?.message || err);
    }
  } else if (isOfflineMode) {
    try {
      extractLearningCloudinaryRefs(readLocalStore(), refs);
    } catch (err: any) {
      console.warn('[Cloudinary Learning Audit] Offline store scan failed:', err?.message || err);
    }
  }

  for (const [key, asset] of collectReferencedLearningCloudinaryAssets()) {
    refs.set(key, asset);
  }
  return refs;
}
function learningCloudinaryPublicIdKey(value: string): string {
  return normalizeLearningCloudinaryId(String(value || '')).toLowerCase();
}
async function destroyCloudinaryLearningAsset(asset: any): Promise<'deleted' | 'missing' | 'failed'> {
  try {
    const result: any = await new Promise((resolve, reject) => {
      cloudinary.uploader.destroy(asset.publicId, { resource_type: asset.resourceType, type: 'upload', invalidate: true }, (error: any, response: any) => error ? reject(error) : resolve(response));
    });
    const outcome = String(result?.result || '').toLowerCase();
    if (outcome === 'ok') return 'deleted';
    if (outcome === 'not found') return 'missing';
    console.warn('[Cloudinary Learning Cleanup] Unexpected delete result:', asset.publicId, outcome || result);
    return 'failed';
  } catch (err: any) {
    console.warn('[Cloudinary Learning Cleanup] Delete failed:', asset.publicId, err?.message || err);
    return 'failed';
  }
}
function extractLearningDriveFileIds(value: any, out = new Set<string>(), depth = 0): Set<string> {
  if (depth > 12 || value == null) return out;
  if (Array.isArray(value)) {
    for (const item of value) extractLearningDriveFileIds(item, out, depth + 1);
    return out;
  }
  if (typeof value === 'object') {
    const type = String((value as any).type || '').toLowerCase();
    const fileId = String((value as any).driveFileId || '').trim();
    if (type === 'pdf' && /^[A-Za-z0-9_-]{10,200}$/.test(fileId)) out.add(fileId);
    for (const item of Object.values(value)) extractLearningDriveFileIds(item, out, depth + 1);
  }
  return out;
}

function extractLocalLearningAssetIds(value: any, out = new Set<string>(), depth = 0): Set<string> {
  if (depth > 12 || value == null) return out;
  if (typeof value === 'string') {
    const match = value.match(/^\/api\/learning-assets\/([A-Za-z0-9._-]{20,180})$/);
    if (match?.[1]) out.add(match[1]);
    return out;
  }
  if (Array.isArray(value)) {
    for (const item of value) extractLocalLearningAssetIds(item, out, depth + 1);
    return out;
  }
  if (typeof value === 'object') {
    for (const item of Object.values(value)) extractLocalLearningAssetIds(item, out, depth + 1);
  }
  return out;
}

function cleanupLocalLearningAssetsForDeletedMaterial(material: any) {
  const candidates = extractLocalLearningAssetIds(material);
  const protectedIds = extractLocalLearningAssetIds([lessonPlans || [], lkpdList || [], exams || [], generatedExams || [], eduGames || [], appSettings || {}]);
  let deleted = 0, protectedCount = 0, failed = 0;
  const root = path.resolve(learningAssetsDir) + path.sep;
  for (const assetId of candidates) {
    if (protectedIds.has(assetId)) { protectedCount++; continue; }
    const filePath = path.resolve(learningAssetsDir, assetId);
    if (!filePath.startsWith(root)) { failed++; continue; }
    try {
      if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
      deleted++;
    } catch {
      failed++;
    }
  }
  return { deleted, protected: protectedCount, failed };
}

async function cleanupLearningAssetsForDeletedMaterial(material: any, req?: any) {
  if (isOfflineMode) return cleanupLocalLearningAssetsForDeletedMaterial(material);

  let deleted = 0, protectedCount = 0, failed = 0;

  const driveCandidates = extractLearningDriveFileIds(material);
  const protectedDriveIds = extractLearningDriveFileIds([lessonPlans || [], lkpdList || [], exams || [], generatedExams || [], eduGames || [], appSettings || {}]);
  if (req) {
    for (const fileId of driveCandidates) {
      if (protectedDriveIds.has(fileId)) { protectedCount++; continue; }
      const outcome = await deleteManagedLearningPdfFromGoogleDrive(fileId, req);
      if (outcome === 'deleted' || outcome === 'missing') deleted++;
      else if (outcome === 'forbidden') protectedCount++;
      else failed++;
    }
  }

  if (process.env.CLOUDINARY_CLOUD_NAME) {
    const candidates = extractLearningCloudinaryRefs(material);
    const protectedRefs = collectReferencedLearningCloudinaryAssets();
    for (const [key, asset] of candidates) {
      if (protectedRefs.has(key)) { protectedCount++; continue; }
      const outcome = await destroyCloudinaryLearningAsset(asset);
      if (outcome === 'deleted' || outcome === 'missing') deleted++; else failed++;
    }
  }
  return { deleted, protected: protectedCount, failed };
}
app.get('/api/cloudinary/learning-assets-audit', requireAuth, requireRole(['admin', 'bos', 'superadmin']), async (req: any, res: any) => {
  try {
    // Pastikan sumber data persisten sudah terhidrasi sebelum audit.
    // Tanpa ini audit yang dipanggil terlalu dini dapat melihat array in-memory
    // yang belum berisi materi dari Cloud SQL/app_store dan salah melaporkan semua
    // asset Cloudinary sebagai orphan.
    await ensureHydrated();

    const remote = await listActualCloudinaryLearningAssets(req);
    const referenceSources: Record<string, any> = {
      lessonPlans,
      lkpdList,
      exams,
      generatedExams,
      eduGames,
      appSettings
    };
    const referenced = await collectPersistedLearningCloudinaryAssets();

    // Exact resource-type match first; public_id fallback prevents false orphan reports
    // when Cloudinary delivery/resource-type representation differs.
    const remoteByPublicId = new Map<string, any>();
    for (const asset of remote.values()) {
      const key = learningCloudinaryPublicIdKey(asset.publicId);
      if (key && !remoteByPublicId.has(key)) remoteByPublicId.set(key, asset);
    }
    const referencedByPublicId = new Map<string, any>();
    for (const asset of referenced.values()) {
      const key = learningCloudinaryPublicIdKey(asset.publicId);
      if (key && !referencedByPublicId.has(key)) referencedByPublicId.set(key, asset);
    }

    const orphaned = [...remote.values()]
      .filter((asset) => {
        const exactKey = asset.resourceType + ':' + asset.publicId;
        if (referenced.has(exactKey)) return false;
        return !referencedByPublicId.has(learningCloudinaryPublicIdKey(asset.publicId));
      })
      .slice(0, 200);

    const typeMismatches = [...remote.values()]
      .filter((asset) => {
        const key = learningCloudinaryPublicIdKey(asset.publicId);
        const ref = referencedByPublicId.get(key);
        if (!ref) return false;
        return !referenced.has(asset.resourceType + ':' + asset.publicId);
      })
      .slice(0, 200);

    const missing = [...referenced.values()]
      .filter((asset) => {
        const exactKey = asset.resourceType + ':' + asset.publicId;
        if (remote.has(exactKey)) return false;
        return !remoteByPublicId.has(learningCloudinaryPublicIdKey(asset.publicId));
      })
      .slice(0, 200);

    return res.json({ success: true, audit: {
      remoteTotal: remote.size,
      referencedTotal: referenced.size,
      orphanedCount: orphaned.length,
      missingReferencedCount: missing.length,
      typeMismatchCount: typeMismatches.length,
      orphanedSample: orphaned,
      missingReferencedSample: missing,
      typeMismatchSample: typeMismatches,
      referenceSourceCounts: Object.fromEntries(
        Object.entries(referenceSources).map(([name, value]) => {
          const refs = extractLearningCloudinaryRefs(value);
          return [name, refs.size];
        })
      ),
      persistedReferenceCount: referenced.size,
      note: 'Audit-only. Tidak ada asset yang dihapus. Data dipastikan terhidrasi sebelum audit. Pencocokan exact resource type + fallback public_id.'
    }});
  } catch (err: any) {
    console.error('[Cloudinary Learning Audit] Failed:', err?.message || err);
    return res.status(500).json({ success: false, message: safeServerError(err, 'Audit aset Materi Ajar gagal.') });
  }
});

app.delete("/api/learning/materials/:id", requireAuth, requireRole(['teacher', 'guru', 'admin', 'bos', 'superadmin']), async (req: any, res) => {
  const resolved = resolveLearningMaterialForRequest(req, req.params.id);
  if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID materi ambigu lintas tenant.' });
  if (!resolved.material || resolved.index < 0) return res.status(404).json({ success: false, message: 'Materi tidak ditemukan pada madrasah ini.' });
  if (isTeacherRequest(req) && !teacherCanUseLearningMaterialPayload(req, resolved.material)) {
    return res.status(403).json({ success: false, message: 'Guru tidak dapat menghapus materi di luar mata pelajaran yang diampu.' });
  }
  const deletedMaterial = resolved.material;
  (lessonPlans as any[]).splice(resolved.index, 1);
  learningProgress = learningProgress.filter((item: any) =>
    !(String(item.materialId || '') === String(req.params.id) && isItemForCurrentMadrasah(item, req))
  );
  await saveDataBatch([
    { key: 'lessonPlans', value: lessonPlans },
    { key: 'learningProgress', value: learningProgress }
  ]);
  const cleanup = await cleanupLearningAssetsForDeletedMaterial(deletedMaterial, req);
  res.json({ success: true, cleanup, materials: learningMaterialsForStaffRequest(req) });
});

app.get("/api/learning/progress", requireAuth, (req: any, res) => {
  const authUser = req.user || getAuthUser(req);
  const role = String(authUser?.role || '').toLowerCase();
  const materialId = String(req.query?.materialId || '').trim();
  const isStudentRole = ['student', 'siswa', 'class_leader', 'ketua_kelas'].includes(role);

  if (isStudentRole) {
    const progress = learningProgressForRequest(req)
      .filter((item: any) => String(item.studentId || '') === String(authUser?.id || ''))
      .filter((item: any) => !materialId || String(item.materialId || '') === materialId);
    return res.json({ success: true, progress });
  }

  if (!staffRoles.has(role)) {
    return res.status(403).json({ success: false, message: 'Akses progress hanya untuk siswa/guru.' });
  }
  if (materialId) {
    const resolved = resolveLearningMaterialForRequest(req, materialId);
    if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID materi ambigu lintas tenant.' });
    if (!resolved.material) return res.status(404).json({ success: false, message: 'Materi tidak ditemukan pada madrasah ini.' });
    if (isTeacherRequest(req) && !teacherCanUseLearningMaterialPayload(req, resolved.material)) {
      return res.status(403).json({ success: false, message: 'Guru hanya dapat memonitor materi mata pelajaran yang diampu.' });
    }
    const classTargets = classTargetsFromLearningMaterial(resolved.material);
    const targetStudents = filterByMadrasah(students || [], req).filter((student: any) => {
      if (classTargets.length === 0 || classTargets.some((value: string) => ['ALL', 'SEMUA KELAS'].includes(value.toUpperCase()))) return true;
      const refs = [student.classId, student.class_id, student.className, student.class].filter(Boolean).map((value: any) => String(value).toLowerCase());
      return classTargets.some((target: string) => refs.includes(String(target).toLowerCase()));
    });
    const progressRows = learningProgressForRequest(req).filter((item: any) => String(item.materialId || '') === materialId);
    const byStudent = new Map(progressRows.map((item: any) => [String(item.studentId || ''), item]));
    const rows = targetStudents.map((student: any) => {
      const progress = byStudent.get(String(student.id || '')) || null;
      const viewedBlockCount = Array.isArray(progress?.viewedBlockIds) ? progress.viewedBlockIds.length : 0;
      return {
        studentId: String(student.id || ''),
        studentName: String(student.name || ''),
        nis: String(student.nis || ''),
        classId: String(student.classId || student.class_id || ''),
        className: String(student.className || ''),
        status: progress?.status || 'not_started',
        progressPercent: Number(progress?.progressPercent || 0),
        activeSeconds: Number(progress?.activeSeconds || 0),
        viewedBlockCount,
        viewedAt: progress?.viewedAt || '',
        completedAt: progress?.completedAt || '',
        updatedAt: progress?.updatedAt || ''
      };
    });
    const completed = rows.filter((row: any) => row.status === 'completed' || row.progressPercent >= 100).length;
    return res.json({ success: true, material: resolved.material, rows, summary: { total: rows.length, completed, inProgress: rows.length - completed } });
  }

  res.json({ success: true, progress: learningProgressForRequest(req) });
});

app.post("/api/learning/progress", requireAuth, requireRole(['student', 'siswa', 'class_leader', 'ketua_kelas']), async (req: any, res) => {
  const authUser = req.user || getAuthUser(req);
  const materialId = String(req.body?.materialId || '').trim();
  if (!materialId || materialId.length > 256) return res.status(400).json({ success: false, message: 'materialId tidak valid.' });
  const own = findStudentForRequest(req, authUser?.id);
  if (own.ambiguous) return res.status(409).json({ success: false, message: 'Identitas siswa ambigu pada tenant ini.' });
  if (!own.student) return res.status(404).json({ success: false, message: 'Identitas siswa tidak ditemukan pada tenant ini.' });
  const resolved = resolveLearningMaterialForRequest(req, materialId);
  if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID materi ambigu lintas tenant.' });
  if (!resolved.material || !studentCanAccessLearningMaterial(own.student, resolved.material)) {
    return res.status(403).json({ success: false, message: 'Materi tidak tersedia untuk akun siswa ini.' });
  }

  const prereq = Array.isArray(resolved.material.prerequisiteMaterialIds) ? resolved.material.prerequisiteMaterialIds.map(String) : [];
  const completedIds = new Set(learningProgressForRequest(req)
    .filter((item: any) => String(item.studentId || '') === String(authUser.id) && (item.status === 'completed' || Number(item.progressPercent || 0) >= 100))
    .map((item: any) => String(item.materialId || '')));
  const lockedBy = prereq.filter((id: string) => !completedIds.has(id));
  if (lockedBy.length > 0) {
    return res.status(423).json({ success: false, message: 'Materi prasyarat belum selesai.', lockedBy });
  }

  const nowIso = new Date().toISOString();
  const key = learningProgressKey(req, authUser.id, materialId);
  const requestedStatus = String(req.body?.status || '').toLowerCase();
  const progressPercent = Math.max(0, Math.min(100, Math.floor(Number(req.body?.progressPercent ?? (requestedStatus === 'completed' ? 100 : 10)) || 0)));
  const activeSeconds = Math.max(0, Math.min(24 * 3600, Math.floor(Number(req.body?.activeSeconds || 0) || 0)));
  const viewedBlockIds = Array.isArray(req.body?.viewedBlockIds)
    ? Array.from(new Set(req.body.viewedBlockIds.map((value: any) => String(value).trim().slice(0, 256)).filter(Boolean))).slice(0, 200)
    : [];

  const existingIndex = (learningProgress || []).findIndex((item: any) =>
    String(item.id || '') === key ||
    (String(item.studentId || '') === String(authUser.id) &&
      String(item.materialId || '') === materialId &&
      isItemForCurrentMadrasah(item, req))
  );
  const existing = existingIndex >= 0 ? learningProgress[existingIndex] : {};
  const existingCompleted = existing.status === 'completed' || Number(existing.progressPercent || 0) >= 100;
  const mergedActiveSeconds = Math.max(activeSeconds, Number(existing.activeSeconds || 0));
  const mergedViewedBlockIds = Array.from(new Set([
    ...(Array.isArray(existing.viewedBlockIds) ? existing.viewedBlockIds : []),
    ...viewedBlockIds
  ].map((value: any) => String(value).trim()).filter(Boolean))).slice(0, 200);
  const mergedProgressPercent = Math.max(progressPercent, Number(existing.progressPercent || 0));
  const completionRequested = requestedStatus === 'completed' || progressPercent >= 100;

  // Reopening or checkpointing an already completed material must never force the
  // student through the engagement gate again. New completions are validated
  // against cumulative server-side checkpoints, not only the latest request.
  if (completionRequested && !existingCompleted) {
    const policy = learningEngagementPolicy(resolved.material);
    if (mergedActiveSeconds < policy.minActiveSeconds) {
      return res.status(423).json({ success: false, message: `Baca materi minimal ${policy.minActiveSeconds} detik aktif sebelum selesai.` });
    }
    if (policy.requireAllBlocks) {
      const requiredBlockIds = learningBlockIds(resolved.material);
      const seen = new Set(mergedViewedBlockIds.map(String));
      if (requiredBlockIds.length > 0 && !requiredBlockIds.every((id: string) => seen.has(id))) {
        return res.status(423).json({ success: false, message: 'Semua bagian materi harus terlihat sebelum selesai.' });
      }
    }
  }

  const finalStatus = existingCompleted || completionRequested
    ? 'completed'
    : (mergedProgressPercent > 0 || requestedStatus === 'viewed' || requestedStatus === 'in_progress' ? 'in_progress' : 'not_started');
  const record = tagNewRecord({
    ...existing,
    id: key,
    materialId,
    studentId: String(authUser.id),
    studentName: String(own.student.name || authUser.name || ''),
    nis: String(own.student.nis || ''),
    classId: String(own.student.classId || own.student.class_id || ''),
    status: finalStatus,
    progressPercent: finalStatus === 'completed' ? 100 : mergedProgressPercent,
    activeSeconds: mergedActiveSeconds,
    viewedBlockIds: mergedViewedBlockIds,
    viewedAt: existing.viewedAt || nowIso,
    completedAt: finalStatus === 'completed' ? (existing.completedAt || nowIso) : (existing.completedAt || ''),
    updatedAt: nowIso,
    source: 'server-authoritative'
  }, req);
  if (existingIndex >= 0) learningProgress[existingIndex] = record;
  else learningProgress.push(record);
  await saveData('learningProgress', learningProgress);
  res.json({ success: true, progress: record });
});

app.get("/api/lesson-plans", (req, res) => {
  const { subjectId } = req.query;
  const filteredTenant = filterLessonPlansForRequest(req);
  if (subjectId) {
    const filtered = filteredTenant.filter(lp => String(lp.subjectId) === String(subjectId));
    return res.json({ success: true, data: filtered, lessonPlans: filtered });
  }
  res.json({ success: true, data: filteredTenant, lessonPlans: filteredTenant });
});

app.post("/api/lesson-plans", async (req, res) => {
  const lp = tagNewRecord(req.body, req);
  if (!lp.id) {
    lp.id = "LP" + Date.now();
    lessonPlans.push(lp);
  } else {
    const resolved = resolveTenantItemIndexById(lessonPlans, lp.id, req, true);
    if (resolved.ambiguous) return res.status(409).json({ success: false, message: 'ID modul ajar ambigu lintas tenant.' });
    const idx = resolved.index;
    if (idx !== -1) {
      lessonPlans[idx] = { ...lessonPlans[idx], ...lp };
    } else {
      lessonPlans.push(lp);
    }
  }
  await saveData('lessonPlans', lessonPlans);
  res.json({ success: true, data: lp, message: "Modul Ajar berhasil disimpan" });
});

app.delete("/api/lesson-plans/:id", async (req, res) => {
  const { id } = req.params;
  lessonPlans = lessonPlans.filter(item => !(String(item.id) === String(id) && isItemForCurrentMadrasah(item, req)));
  await saveData('lessonPlans', lessonPlans);
  res.json({ success: true, message: "Modul Ajar berhasil dihapus" });
});

app.get("/api/import-groups", (req, res) => {
  const { subjectId } = req.query;
  let list = filterByMadrasah(importGroups || [], req);
  if (subjectId) list = list.filter((g: any) => String(g.subjectId) === String(subjectId));
  res.json({ success: true, data: list });
});

app.post("/api/import-groups", async (req, res) => {
  const raw = req.body && typeof req.body === 'object' ? { ...req.body } : {};
  delete raw.madrasahId;
  delete raw.madrasahSlug;
  if (!raw.id) raw.id = "grp_" + Date.now() + "_" + Math.random().toString(36).substring(2, 6);
  const grp = tagNewRecord(raw, req);
  const idx = importGroups.findIndex((g: any) => String(g.id) === String(grp.id) && isItemForCurrentMadrasah(g, req));
  if (idx !== -1) importGroups[idx] = { ...importGroups[idx], ...grp };
  else importGroups.push(grp);
  await saveData('importGroups', importGroups);
  res.json({ success: true, data: grp, message: "Kelompok berhasil disimpan" });
});

app.delete("/api/import-groups/:id", async (req, res) => {
  const { id } = req.params;
  importGroups = importGroups.filter((g: any) => !(String(g.id) === String(id) && isItemForCurrentMadrasah(g, req)));
  await saveData('importGroups', importGroups);
  res.json({ success: true, message: "Kelompok berhasil dihapus" });
});

function detectSubjectCategoryServer(subjectName = '', topic = '', materiDetail = '') {
  const raw = `${subjectName} ${topic} ${materiDetail}`.toLowerCase();
  
  if (
    raw.includes('koding') || raw.includes('coding') || raw.includes('ai') || raw.includes('informatika') || 
    raw.includes('sistem komputer') || raw.includes('komputer') || raw.includes('arduino') || raw.includes('python') || 
    raw.includes('algoritma') || raw.includes('siber') || raw.includes('cyber') || raw.includes('mikrokontroler') || 
    raw.includes('single board') || raw.includes('c++') || raw.includes('unoardusim') || raw.includes('iot') ||
    raw.includes('pemrograman') || raw.includes('tinkercad')
  ) {
    return 'koding_ai';
  }
  
  if (
    raw.includes('arab') || raw.includes('lughah') || raw.includes('hiwar') || raw.includes('nahwu') || 
    raw.includes('sharaf') || raw.includes('mufradat') || raw.includes('qira') || raw.includes('kitabah')
  ) {
    return 'bahasa_arab';
  }

  if (
    raw.includes('pai') || raw.includes('agama') || raw.includes('quran') || raw.includes('hadis') || 
    raw.includes('fikih') || raw.includes('fiqih') || raw.includes('akidah') || raw.includes('akhlak') || 
    raw.includes('ski') || raw.includes('sejarah kebudayaan islam') || raw.includes('islam') || raw.includes('tajwid')
  ) {
    return 'pai_madrasah';
  }

  return 'umum';
}


